var ENG=[{"id":"loan-emi","name":"Loan instalment (EMI)","fn":"Finance","sectors":["*"],"kw":["loan","emi","instalment","mortgage","repayment","borrow","interest"],"about":"Works out the regular repayment on a loan and how much interest you pay in total.","process":["Turn the yearly rate into a rate per payment period.","Count the total number of payments.","Apply the level-payment formula, then add up all payments and subtract the amount borrowed."],"inputs":[{"key":"principal","label":"Loan amount","unit":"money","sample":"1000000"},{"key":"rate","label":"Yearly interest rate","unit":"%","sample":"9"},{"key":"years","label":"Loan period","unit":"years","sample":"5"},{"key":"ppy","label":"Payments per year","unit":"count","sample":"12"}],"steps":[{"key":"r","label":"Rate per payment period","unit":"ratio","f":"rate/100/ppy","x":"Yearly rate divided by payments per year"},{"key":"n","label":"Number of payments","unit":"count","f":"years*ppy","x":""},{"key":"emi","label":"Instalment per period","unit":"money","f":"PMT(r,n,principal)","x":"Level payment that clears the loan exactly"},{"key":"total","label":"Total paid","unit":"money","f":"emi*n","x":""},{"key":"interest","label":"Total interest","unit":"money","f":"total-principal","x":""}],"out":["emi","total","interest"],"checks":[{"label":"Total paid is not less than the amount borrowed","f":"total>=principal-0.01"},{"label":"Instalments repay the loan in full","f":"ABS(PV(r,n,emi)-principal)<0.01*MAX(1,principal/1000)"}],"notes":["Fixed rate and equal instalments assumed. Fees, insurance and changes in rate are not included."]},{"id":"npv-irr","name":"Investment appraisal: NPV, IRR and payback","fn":"Finance","sectors":["*"],"kw":["npv","irr","payback","investment","appraisal","capex","project","return","discount","cash","flows"],"about":"Judges whether an investment is worth doing from its yearly cash flows.","process":["List the money out (negative) and money in (positive) for each year, starting with year 0.","Discount each year back to today at your required return.","Add them up for NPV; find the rate that makes NPV zero for IRR; find when the running total turns positive for payback."],"inputs":[{"key":"rate","label":"Required return (discount rate)","unit":"%","sample":"12"},{"key":"cf","label":"Cash flows, year 0 first","unit":"series","sample":"-100000,30000,35000,40000,45000"}],"steps":[{"key":"npv","label":"Net present value","unit":"money","f":"NPV0(rate/100,cf)","x":"Sum of each year's cash flow divided by (1 plus rate) to the power of the year"},{"key":"irr","label":"Internal rate of return","unit":"ratio","f":"IRR(cf)","x":"Rate at which NPV is zero"},{"key":"irrpct","label":"IRR in percent","unit":"%","f":"irr*100","x":""},{"key":"payback","label":"Payback period","unit":"years","f":"PAYBACK(cf)","x":"Years until money in has repaid money out; -1 means not within the series"},{"key":"pi","label":"Profitability index","unit":"ratio","f":"(npv-FIRST(cf))/(0-FIRST(cf))","x":"Present value of inflows divided by the amount invested"},{"key":"decision","label":"Worth doing (1 yes, 0 no)","unit":"flag","f":"IF(npv>0,1,0)","x":""}],"out":["npv","irrpct","payback","pi","decision"],"checks":[{"label":"NPV at the IRR is close to zero","f":"ABS(NPV0(irr,cf))<0.5"},{"label":"First cash flow is money out","f":"FIRST(cf)<0"}],"notes":["Cash flows are assumed to arrive at year end. Add tax and working capital to your cash flows before using this."]},{"id":"dscr","name":"Debt service cover (DSCR)","fn":"Finance","sectors":["Banking and insurance","Construction and real estate","Energy and utilities","Manufacturing","Technology and services"],"kw":["dscr","lender","covenant","debt","service","coverage","bank","loan","cover"],"about":"Shows how comfortably operating income covers loan repayments, the first thing a lender looks at.","process":["Take income available for debt service for the year.","Add the loan interest and principal due in the same year.","Divide income by debt service and compare with the lender's minimum."],"inputs":[{"key":"income","label":"Income available for debt service","unit":"money","sample":"2400000"},{"key":"interest","label":"Interest due in the year","unit":"money","sample":"600000"},{"key":"principal","label":"Principal due in the year","unit":"money","sample":"1000000"},{"key":"minimum","label":"Lender minimum cover","unit":"times","sample":"1.25"}],"steps":[{"key":"service","label":"Total debt service","unit":"money","f":"interest+principal","x":""},{"key":"dscr","label":"Debt service cover","unit":"times","f":"income/service","x":""},{"key":"headroom","label":"Income could fall by (percent) before breach","unit":"%","f":"(1-minimum*service/income)*100","x":""},{"key":"ok","label":"Meets the lender minimum (1 yes, 0 no)","unit":"flag","f":"IF(dscr>=minimum,1,0)","x":""}],"out":["dscr","headroom","ok"],"checks":[{"label":"Debt service is above zero","f":"service>0"}],"notes":["Lenders define income differently. Use the definition in your loan agreement."]},{"id":"wacc","name":"Weighted average cost of capital","fn":"Finance","sectors":["*"],"kw":["wacc","cost","capital","equity","debt","discount","rate","hurdle"],"about":"Blends the cost of equity and the after-tax cost of debt into one discount rate.","process":["Work out the share of equity and debt in total funding.","Reduce the cost of debt by the tax saving.","Weight each cost by its share and add."],"inputs":[{"key":"equity","label":"Equity value","unit":"money","sample":"6000000"},{"key":"debt","label":"Debt value","unit":"money","sample":"4000000"},{"key":"ke","label":"Cost of equity","unit":"%","sample":"15"},{"key":"kd","label":"Cost of debt before tax","unit":"%","sample":"9"},{"key":"tax","label":"Tax rate","unit":"%","sample":"25"}],"steps":[{"key":"total","label":"Total funding","unit":"money","f":"equity+debt","x":""},{"key":"we","label":"Share of equity","unit":"ratio","f":"equity/total","x":""},{"key":"wd","label":"Share of debt","unit":"ratio","f":"debt/total","x":""},{"key":"kdat","label":"Cost of debt after tax","unit":"%","f":"kd*(1-tax/100)","x":""},{"key":"wacc","label":"WACC","unit":"%","f":"we*ke+wd*kdat","x":""}],"out":["wacc","kdat"],"checks":[{"label":"Shares add to one","f":"ABS(we+wd-1)<0.000001"}],"notes":["Use market values where you can. Cost of equity can be set from your own required return."]},{"id":"cagr","name":"Growth rate over time (CAGR)","fn":"Finance","sectors":["*"],"kw":["cagr","growth","rate","compound","annual","increase","trend"],"about":"Gives the steady yearly growth rate that takes a starting value to an ending value.","process":["Divide ending value by starting value.","Take the root for the number of years and subtract one."],"inputs":[{"key":"start","label":"Starting value","unit":"number","sample":"1000"},{"key":"end","label":"Ending value","unit":"number","sample":"1610.51"},{"key":"years","label":"Number of years","unit":"years","sample":"5"}],"steps":[{"key":"ratio","label":"End divided by start","unit":"ratio","f":"end/start","x":""},{"key":"cagr","label":"CAGR","unit":"%","f":"(POW(ratio,1/years)-1)*100","x":""},{"key":"check_end","label":"Start grown at CAGR","unit":"number","f":"start*POW(1+cagr/100,years)","x":""}],"out":["cagr"],"checks":[{"label":"Growing the start at CAGR reaches the end","f":"ABS(check_end-end)<0.0001*MAX(1,ABS(end))"},{"label":"Start must be above zero","f":"start>0"}],"notes":[]},{"id":"sip-future","name":"Regular saving: future value","fn":"Finance","sectors":["*"],"kw":["sip","savings","invest","monthly","future","value","retirement","fund","goal"],"about":"Shows what regular saving grows to at an assumed return.","process":["Convert the yearly return to a rate per period.","Apply the future-value-of-payments formula.","Compare with the total you put in."],"inputs":[{"key":"pmt","label":"Amount saved each period","unit":"money","sample":"5000"},{"key":"rate","label":"Expected yearly return","unit":"%","sample":"10"},{"key":"years","label":"Years","unit":"years","sample":"15"},{"key":"ppy","label":"Periods per year","unit":"count","sample":"12"}],"steps":[{"key":"r","label":"Rate per period","unit":"ratio","f":"rate/100/ppy","x":""},{"key":"n","label":"Number of periods","unit":"count","f":"years*ppy","x":""},{"key":"fv","label":"Value at the end","unit":"money","f":"FV(r,n,pmt)","x":""},{"key":"put","label":"Total you put in","unit":"money","f":"pmt*n","x":""},{"key":"gain","label":"Growth earned","unit":"money","f":"fv-put","x":""}],"out":["fv","put","gain"],"checks":[{"label":"Value at the end is not less than what was put in","f":"fv>=put-0.01"}],"notes":["A return is not guaranteed. Try lower returns to see how the result changes."]},{"id":"bond-price","name":"Bond price and yield","fn":"Finance","sectors":["Banking and insurance","Public sector and social enterprise","Technology and services","Energy and utilities"],"kw":["bond","price","yield","coupon","maturity","fixed","income","debenture"],"about":"Prices a bond that pays a coupon each year and returns face value at the end.","process":["Discount each coupon at the market yield.","Discount the face value repaid at the end.","Add the two parts."],"inputs":[{"key":"face","label":"Face value","unit":"money","sample":"1000"},{"key":"coupon","label":"Coupon rate","unit":"%","sample":"8"},{"key":"yld","label":"Market yield","unit":"%","sample":"9"},{"key":"years","label":"Years to maturity","unit":"years","sample":"5"}],"steps":[{"key":"c","label":"Coupon per year","unit":"money","f":"face*coupon/100","x":""},{"key":"pvc","label":"Present value of coupons","unit":"money","f":"PV(yld/100,years,c)","x":""},{"key":"pvf","label":"Present value of face value","unit":"money","f":"face/POW(1+yld/100,years)","x":""},{"key":"price","label":"Bond price","unit":"money","f":"pvc+pvf","x":""},{"key":"prem","label":"Price compared with face value (percent)","unit":"%","f":"(price/face-1)*100","x":""}],"out":["price","prem"],"checks":[{"label":"Price is above face value only if the yield is below the coupon","f":"IF(yld<coupon,price>face,price<=face)=1"}],"notes":["Annual coupons assumed."]},{"id":"lease-vs-buy","name":"Lease or buy","fn":"Finance","sectors":["Manufacturing","Technology and services","Logistics and supply chain","Healthcare","Retail and e-commerce","Construction and real estate","Energy and utilities"],"kw":["lease","buy","rent","purchase","asset","decision","equipment"],"about":"Compares the present cost of leasing an asset with buying it.","process":["Discount the lease payments over the lease term.","Take the purchase price less the present value of what you could sell it for at the end.","The lower present cost is the better choice, before non-money factors."],"inputs":[{"key":"price","label":"Purchase price","unit":"money","sample":"2000000"},{"key":"lease","label":"Lease payment per year","unit":"money","sample":"520000"},{"key":"years","label":"Lease term","unit":"years","sample":"5"},{"key":"resale","label":"Value at the end if bought","unit":"money","sample":"600000"},{"key":"rate","label":"Your discount rate","unit":"%","sample":"11"}],"steps":[{"key":"pvlease","label":"Present cost of leasing","unit":"money","f":"PV(rate/100,years,lease)","x":""},{"key":"pvresale","label":"Present value of resale","unit":"money","f":"resale/POW(1+rate/100,years)","x":""},{"key":"pvbuy","label":"Present cost of buying","unit":"money","f":"price-pvresale","x":""},{"key":"saving","label":"Buying costs less by","unit":"money","f":"pvlease-pvbuy","x":""},{"key":"choice","label":"Better choice (1 buy, 0 lease)","unit":"flag","f":"IF(pvbuy<pvlease,1,0)","x":""}],"out":["pvlease","pvbuy","saving","choice"],"checks":[{"label":"Present costs are above zero","f":"AND(pvlease>0,pvbuy>0)"}],"notes":["Maintenance, tax benefits and financing terms differ between deals; add them to the payments if they matter."]},{"id":"dcf-value","name":"Business value by discounted cash flow","fn":"Finance","sectors":["*"],"kw":["dcf","valuation","enterprise","value","terminal","growth","worth","company"],"about":"Values a business from forecast free cash flows plus a value for the years after the forecast.","process":["Discount each forecast year's free cash flow.","Estimate the value after the last year using a steady growth rate.","Discount that value back and add everything.","Subtract debt and add cash to reach the value to owners."],"inputs":[{"key":"fcf","label":"Free cash flow, year 1 first","unit":"series","sample":"500000,560000,620000,680000,740000"},{"key":"wacc","label":"Discount rate","unit":"%","sample":"12"},{"key":"g","label":"Long-run growth after forecast","unit":"%","sample":"4"},{"key":"debt","label":"Debt","unit":"money","sample":"1500000"},{"key":"cash","label":"Cash","unit":"money","sample":"300000"}],"steps":[{"key":"pvfcf","label":"Present value of forecast years","unit":"money","f":"NPV(wacc/100,fcf)","x":""},{"key":"tv","label":"Value after the forecast years","unit":"money","f":"LAST(fcf)*(1+g/100)/((wacc-g)/100)","x":""},{"key":"n","label":"Forecast years","unit":"count","f":"LEN(fcf)","x":""},{"key":"pvtv","label":"Present value of that value","unit":"money","f":"tv/POW(1+wacc/100,n)","x":""},{"key":"ev","label":"Enterprise value","unit":"money","f":"pvfcf+pvtv","x":""},{"key":"equity","label":"Value to owners","unit":"money","f":"ev-debt+cash","x":""},{"key":"tvshare","label":"Share of value that comes after the forecast","unit":"%","f":"pvtv/ev*100","x":""}],"out":["ev","equity","tvshare"],"checks":[{"label":"Discount rate is above growth","f":"wacc>g"},{"label":"Value is above zero","f":"ev>0"}],"notes":["Most of the value often sits after the forecast, so test other growth and discount rates. Figures here are teaching samples."]},{"id":"real-return","name":"Real return after inflation","fn":"Economics","sectors":["*"],"kw":["inflation","real","return","nominal","purchasing","power","interest"],"about":"Shows what an investment really earns once inflation is taken out.","process":["Convert both rates to ratios.","Divide (1 plus nominal) by (1 plus inflation) and subtract one."],"inputs":[{"key":"nominal","label":"Nominal return","unit":"%","sample":"9"},{"key":"inflation","label":"Inflation","unit":"%","sample":"5"}],"steps":[{"key":"real","label":"Real return","unit":"%","f":"((1+nominal/100)/(1+inflation/100)-1)*100","x":""},{"key":"approx","label":"Quick estimate (nominal minus inflation)","unit":"%","f":"nominal-inflation","x":""}],"out":["real"],"checks":[{"label":"Quick estimate is close to the exact figure for small rates","f":"ABS(real-approx)<IF(nominal>20,5,1)"}],"notes":[]},{"id":"ratio-pack","name":"Financial ratios pack","fn":"Accounting","sectors":["*"],"kw":["ratio","ratios","liquidity","solvency","profitability","current","quick","debt","equity","margin","roe","roa","analysis","statements","review"],"about":"Turns the main lines of a balance sheet and profit statement into the ratios lenders, investors and auditors ask for.","process":["Enter the lines from the profit statement and balance sheet.","Each ratio is shown with its formula, so the working can be checked.","Compare each ratio with your sector's usual range and with your own history."],"inputs":[{"key":"revenue","label":"Revenue","unit":"money","sample":"12000000"},{"key":"cogs","label":"Cost of goods sold","unit":"money","sample":"7800000"},{"key":"opex","label":"Operating expenses","unit":"money","sample":"2600000"},{"key":"interest","label":"Interest expense","unit":"money","sample":"350000"},{"key":"tax","label":"Tax","unit":"money","sample":"300000"},{"key":"ca","label":"Current assets","unit":"money","sample":"4200000"},{"key":"inv","label":"Inventory","unit":"money","sample":"1500000"},{"key":"cl","label":"Current liabilities","unit":"money","sample":"2800000"},{"key":"ta","label":"Total assets","unit":"money","sample":"9500000"},{"key":"debt","label":"Total debt","unit":"money","sample":"3600000"},{"key":"eq","label":"Shareholders' equity","unit":"money","sample":"4300000"}],"steps":[{"key":"gp","label":"Gross profit","unit":"money","f":"revenue-cogs","x":""},{"key":"ebit","label":"Operating profit (EBIT)","unit":"money","f":"gp-opex","x":""},{"key":"ni","label":"Net profit","unit":"money","f":"ebit-interest-tax","x":""},{"key":"gm","label":"Gross margin","unit":"%","f":"gp/revenue*100","x":""},{"key":"om","label":"Operating margin","unit":"%","f":"ebit/revenue*100","x":""},{"key":"nm","label":"Net margin","unit":"%","f":"ni/revenue*100","x":""},{"key":"cr","label":"Current ratio","unit":"times","f":"ca/cl","x":"Current assets divided by current liabilities"},{"key":"qr","label":"Quick ratio","unit":"times","f":"(ca-inv)/cl","x":"Excludes inventory"},{"key":"de","label":"Debt to equity","unit":"times","f":"debt/eq","x":""},{"key":"ic","label":"Interest cover","unit":"times","f":"ebit/interest","x":""},{"key":"roe","label":"Return on equity","unit":"%","f":"ni/eq*100","x":""},{"key":"roa","label":"Return on assets","unit":"%","f":"ni/ta*100","x":""},{"key":"at","label":"Asset turnover","unit":"times","f":"revenue/ta","x":""}],"out":["gm","nm","cr","de","ic","roe"],"checks":[{"label":"Gross profit not above revenue","f":"gp<=revenue"},{"label":"Debt plus equity do not exceed total assets by more than the liabilities","f":"debt+eq<=ta+cl"}],"notes":["Ratios depend on how each line is defined in your accounts. Teach-by-example sample numbers are used until you enter your own."]},{"id":"roe-breakdown","name":"Why is return on equity what it is","fn":"Accounting","sectors":["*"],"kw":["roe","breakdown","three","part","return","equity","margin","turnover","leverage"],"about":"Splits return on equity into margin, asset use and borrowing so you can see what drives it.","process":["Net margin = profit / revenue.","Asset turnover = revenue / assets.","Leverage = assets / equity.","Multiply the three to get return on equity."],"inputs":[{"key":"ni","label":"Net profit","unit":"money","sample":"700000"},{"key":"revenue","label":"Revenue","unit":"money","sample":"12000000"},{"key":"ta","label":"Total assets","unit":"money","sample":"9500000"},{"key":"eq","label":"Equity","unit":"money","sample":"4300000"}],"steps":[{"key":"nm","label":"Net margin","unit":"ratio","f":"ni/revenue","x":""},{"key":"at","label":"Asset turnover","unit":"times","f":"revenue/ta","x":""},{"key":"lev","label":"Leverage","unit":"times","f":"ta/eq","x":""},{"key":"roe","label":"Return on equity","unit":"%","f":"nm*at*lev*100","x":""},{"key":"direct","label":"Direct check: profit / equity","unit":"%","f":"ni/eq*100","x":""}],"out":["roe","nm","at","lev"],"checks":[{"label":"The three parts multiply to the direct figure","f":"ABS(roe-direct)<0.0001"}],"notes":[]},{"id":"depreciation","name":"Depreciation schedule","fn":"Accounting","sectors":["*"],"kw":["depreciation","asset","straight","line","written","down","value","wdv","book","value"],"about":"Spreads the cost of an asset over its life using straight-line or declining-balance method.","process":["Take cost less expected value at the end.","Straight-line: equal charge each year.","Declining balance: a fixed percentage of the remaining book value."],"inputs":[{"key":"cost","label":"Cost of asset","unit":"money","sample":"1000000"},{"key":"salvage","label":"Value at the end of life","unit":"money","sample":"100000"},{"key":"life","label":"Useful life","unit":"years","sample":"5"},{"key":"wdvrate","label":"Declining-balance rate","unit":"%","sample":"30"}],"steps":[{"key":"sl","label":"Straight-line charge per year","unit":"money","f":"(cost-salvage)/life","x":""},{"key":"bookSL","label":"Book value after full life (straight-line)","unit":"money","f":"cost-sl*life","x":""},{"key":"wdv1","label":"Declining-balance charge in year 1","unit":"money","f":"cost*wdvrate/100","x":""},{"key":"wdvN","label":"Book value after the life (declining balance)","unit":"money","f":"cost*POW(1-wdvrate/100,life)","x":""}],"out":["sl","bookSL","wdv1","wdvN"],"checks":[{"label":"Straight-line ends at the value at end of life","f":"ABS(bookSL-salvage)<0.01"},{"label":"Salvage not above cost","f":"salvage<=cost"}],"notes":["Tax rules in your country may require different rates or methods."]},{"id":"trial-balance","name":"Trial balance check","fn":"Accounting","sectors":["*"],"kw":["trial","balance","debit","credit","books","check","ledger","difference"],"about":"Checks that total debits equal total credits.","process":["Paste the debit balances and credit balances.","Add each side. If they differ, the difference is what to look for."],"inputs":[{"key":"debits","label":"Debit balances","unit":"series","sample":"150000,42000,18000,9500"},{"key":"credits","label":"Credit balances","unit":"series","sample":"100000,60000,40000,19500"}],"steps":[{"key":"td","label":"Total debits","unit":"money","f":"SUM(debits)","x":""},{"key":"tc","label":"Total credits","unit":"money","f":"SUM(credits)","x":""},{"key":"diff","label":"Difference","unit":"money","f":"td-tc","x":""},{"key":"balanced","label":"Books balance (1 yes, 0 no)","unit":"flag","f":"IF(ABS(diff)<0.005,1,0)","x":""}],"out":["td","tc","diff","balanced"],"checks":[{"label":"Totals are not empty","f":"td+tc>0"}],"notes":[]},{"id":"markup-margin","name":"Markup, margin and price","fn":"Accounting","sectors":["Retail and e-commerce","Manufacturing","Technology and services","Hospitality and travel","Agriculture and food","Logistics and supply chain"],"kw":["markup","margin","price","selling","cost","gross","profit","pricing"],"about":"Moves between cost, selling price, markup and margin, which are often confused.","process":["Margin is profit as a share of price; markup is profit as a share of cost."],"inputs":[{"key":"cost","label":"Cost","unit":"money","sample":"800"},{"key":"markup","label":"Markup wanted","unit":"%","sample":"25"}],"steps":[{"key":"price","label":"Selling price","unit":"money","f":"cost*(1+markup/100)","x":""},{"key":"profit","label":"Profit per unit","unit":"money","f":"price-cost","x":""},{"key":"margin","label":"Margin","unit":"%","f":"profit/price*100","x":""}],"out":["price","profit","margin"],"checks":[{"label":"Markup recovered from price and cost","f":"ABS(profit/cost*100-markup)<0.0001"}],"notes":[]},{"id":"sales-tax","name":"Sales tax / VAT / GST invoice","fn":"Tax","sectors":["*"],"kw":["gst","vat","sales","tax","invoice","inclusive","exclusive","tax","amount"],"about":"Adds tax to a net price, or takes it out of a tax-inclusive price.","process":["Net price plus rate gives the gross price.","Gross price divided by (1 plus rate) gives the net price back."],"inputs":[{"key":"net","label":"Price before tax","unit":"money","sample":"10000"},{"key":"rate","label":"Tax rate","unit":"%","sample":"18"}],"steps":[{"key":"tax","label":"Tax","unit":"money","f":"net*rate/100","x":""},{"key":"gross","label":"Price with tax","unit":"money","f":"net+tax","x":""},{"key":"back","label":"Net recovered from gross","unit":"money","f":"gross/(1+rate/100)","x":""}],"out":["tax","gross"],"checks":[{"label":"Taking tax out returns the original price","f":"ABS(back-net)<0.005"}],"notes":["Use the rate that applies to your goods and place. Rules on input credit and reverse charge differ; ask your adviser."]},{"id":"bank-rec","name":"Bank reconciliation","fn":"Accounting","sectors":["*"],"kw":["bank","reconciliation","cash","book","statement","unpresented","cheques","outstanding","deposits"],"about":"Matches the cash book balance to the bank statement balance.","process":["Start from the bank statement balance.","Add deposits not yet credited by the bank; subtract payments not yet cleared.","The result should equal the cash book balance."],"inputs":[{"key":"bankbal","label":"Bank statement balance","unit":"money","sample":"523400"},{"key":"deposits","label":"Deposits in transit","unit":"money","sample":"45000"},{"key":"unpresented","label":"Payments not yet cleared","unit":"money","sample":"38500"},{"key":"cashbook","label":"Cash book balance","unit":"money","sample":"529900"}],"steps":[{"key":"adjusted","label":"Adjusted bank balance","unit":"money","f":"bankbal+deposits-unpresented","x":""},{"key":"diff","label":"Unexplained difference","unit":"money","f":"adjusted-cashbook","x":""},{"key":"agrees","label":"Agrees (1 yes, 0 no)","unit":"flag","f":"IF(ABS(diff)<0.005,1,0)","x":""}],"out":["adjusted","diff","agrees"],"checks":[{"label":"Difference is not larger than the balance","f":"ABS(diff)<=ABS(cashbook)"}],"notes":[]},{"id":"cash-forecast","name":"Cash forecast by period","fn":"Cash flow","sectors":["*"],"kw":["cash","flow","forecast","weekly","monthly","receipts","payments","closing","balance","runway","budget"],"about":"Builds a period-by-period cash forecast and shows the lowest cash point.","process":["List expected receipts and payments for each period.","Net cash is receipts less payments.","Closing cash is the opening cash plus the running total of net cash."],"inputs":[{"key":"opening","label":"Opening cash","unit":"money","sample":"400000"},{"key":"receipts","label":"Receipts per period","unit":"series","sample":"300000,320000,280000,350000,400000,380000"},{"key":"payments","label":"Payments per period","unit":"series","sample":"340000,310000,360000,330000,320000,300000"}],"steps":[{"key":"net","label":"Net cash per period","unit":"series","f":"receipts-payments","x":""},{"key":"closing","label":"Closing cash per period","unit":"series","f":"opening+CUMSUM(net)","x":""},{"key":"low","label":"Lowest closing cash","unit":"money","f":"MIN(closing)","x":""},{"key":"last","label":"Final closing cash","unit":"money","f":"LAST(closing)","x":""},{"key":"ok","label":"Cash stays above zero (1 yes, 0 no)","unit":"flag","f":"IF(low>=0,1,0)","x":""}],"out":["low","last","ok"],"checks":[{"label":"Final closing equals opening plus total net","f":"ABS(last-(opening+SUM(net)))<0.01"}],"notes":[]},{"id":"runway","name":"Cash runway","fn":"Cash flow","sectors":["Technology and services","Healthcare","Education and training","Public sector and social enterprise","Retail and e-commerce"],"kw":["runway","burn","rate","months","cash","startup","survive"],"about":"Shows how many months cash lasts at the current rate of spending.","process":["Burn is cash spent less cash received each month.","Runway is cash in hand divided by burn."],"inputs":[{"key":"cash","label":"Cash in hand","unit":"money","sample":"2400000"},{"key":"spend","label":"Monthly cash spent","unit":"money","sample":"520000"},{"key":"income","label":"Monthly cash received","unit":"money","sample":"190000"}],"steps":[{"key":"burn","label":"Net monthly burn","unit":"money","f":"spend-income","x":""},{"key":"months","label":"Runway in months","unit":"months","f":"IF(burn>0,cash/burn,999)","x":""}],"out":["burn","months"],"checks":[{"label":"Spend and income are not negative","f":"AND(spend>=0,income>=0)"}],"notes":["999 means income covers spending and cash is not running down."]},{"id":"fcf-bridge","name":"From profit to free cash flow","fn":"Cash flow","sectors":["*"],"kw":["free","cash","flow","fcf","ebitda","operating","cash","capex","working","capital","conversion"],"about":"Walks from operating profit to the cash the business really frees up.","process":["Start from EBITDA.","Subtract tax paid, increase in working capital and capital spending.","What remains is free cash flow to the firm."],"inputs":[{"key":"ebitda","label":"EBITDA","unit":"money","sample":"3100000"},{"key":"tax","label":"Tax paid","unit":"money","sample":"620000"},{"key":"wc","label":"Increase in working capital","unit":"money","sample":"280000"},{"key":"capex","label":"Capital spending","unit":"money","sample":"900000"}],"steps":[{"key":"fcf","label":"Free cash flow","unit":"money","f":"ebitda-tax-wc-capex","x":""},{"key":"conv","label":"Cash conversion of EBITDA","unit":"%","f":"fcf/ebitda*100","x":""}],"out":["fcf","conv"],"checks":[{"label":"Cash conversion cannot exceed 100% unless working capital fell","f":"IF(wc>=0,conv<=100,1)=1"}],"notes":[]},{"id":"cash-cycle","name":"Working capital and cash conversion cycle","fn":"Cash flow","sectors":["Retail and e-commerce","Manufacturing","Agriculture and food","Logistics and supply chain","Technology and services","Healthcare"],"kw":["dso","dio","dpo","cash","conversion","cycle","receivables","inventory","payables","days","working","capital"],"about":"Counts the days between paying suppliers and collecting from customers.","process":["Days sales outstanding = receivables / revenue x days.","Days inventory = inventory / cost of goods x days.","Days payables = payables / cost of goods x days.","Cycle = DSO + DIO - DPO."],"inputs":[{"key":"revenue","label":"Revenue for the period","unit":"money","sample":"12000000"},{"key":"cogs","label":"Cost of goods sold for the period","unit":"money","sample":"7800000"},{"key":"ar","label":"Receivables","unit":"money","sample":"1900000"},{"key":"inv","label":"Inventory","unit":"money","sample":"1500000"},{"key":"ap","label":"Payables","unit":"money","sample":"1200000"},{"key":"days","label":"Days in the period","unit":"days","sample":"365"}],"steps":[{"key":"dso","label":"Days sales outstanding","unit":"days","f":"ar/revenue*days","x":""},{"key":"dio","label":"Days inventory held","unit":"days","f":"inv/cogs*days","x":""},{"key":"dpo","label":"Days payables","unit":"days","f":"ap/cogs*days","x":""},{"key":"ccc","label":"Cash conversion cycle","unit":"days","f":"dso+dio-dpo","x":""},{"key":"wc","label":"Money tied up in working capital","unit":"money","f":"ar+inv-ap","x":""}],"out":["dso","dio","dpo","ccc","wc"],"checks":[{"label":"Cycle is the sum of its parts","f":"ABS(ccc-(dso+dio-dpo))<0.0001"}],"notes":[]},{"id":"breakeven","name":"Break-even point","fn":"Costing","sectors":["*"],"kw":["break","even","contribution","fixed","cost","variable","cost","margin","of","safety","units","sales"],"about":"Finds the sales volume at which total revenue equals total cost.","process":["Contribution per unit = price less variable cost.","Break-even units = fixed cost / contribution per unit.","Margin of safety shows how far expected sales are above break-even."],"inputs":[{"key":"fixed","label":"Fixed costs for the period","unit":"money","sample":"900000"},{"key":"price","label":"Selling price per unit","unit":"money","sample":"450"},{"key":"vc","label":"Variable cost per unit","unit":"money","sample":"270"},{"key":"expected","label":"Expected units sold","unit":"units","sample":"6500"}],"steps":[{"key":"cm","label":"Contribution per unit","unit":"money","f":"price-vc","x":""},{"key":"be","label":"Break-even units","unit":"units","f":"fixed/cm","x":""},{"key":"bevalue","label":"Break-even sales value","unit":"money","f":"be*price","x":""},{"key":"mos","label":"Margin of safety","unit":"%","f":"(expected-be)/expected*100","x":""},{"key":"profit","label":"Expected profit","unit":"money","f":"expected*cm-fixed","x":""}],"out":["be","bevalue","mos","profit"],"checks":[{"label":"Price is above variable cost","f":"price>vc"},{"label":"Profit at break-even is zero","f":"ABS(be*cm-fixed)<0.01"}],"notes":[]},{"id":"unit-cost","name":"Full cost and selling price per unit","fn":"Costing","sectors":["Manufacturing","Electronics and semiconductor","Agriculture and food","Retail and e-commerce","Technology and services","Construction and real estate","Hospitality and travel"],"kw":["full","cost","absorption","unit","cost","overhead","price","labour","material","product","costing"],"about":"Adds every cost of making and selling one unit and sets a price for the profit you want.","process":["Add materials and labour to get prime cost.","Spread factory overhead across the units made.","Add selling and admin costs per unit.","Add the profit you want to reach the price."],"inputs":[{"key":"units","label":"Units made in the period","unit":"units","sample":"10000"},{"key":"material","label":"Material cost per unit","unit":"money","sample":"120"},{"key":"labour","label":"Labour cost per unit","unit":"money","sample":"45"},{"key":"factory","label":"Factory overhead for the period","unit":"money","sample":"450000"},{"key":"selling","label":"Selling and admin cost for the period","unit":"money","sample":"300000"},{"key":"margin","label":"Profit wanted as share of price","unit":"%","sample":"20"}],"steps":[{"key":"prime","label":"Prime cost per unit","unit":"money","f":"material+labour","x":""},{"key":"ohu","label":"Factory overhead per unit","unit":"money","f":"factory/units","x":""},{"key":"production","label":"Production cost per unit","unit":"money","f":"prime+ohu","x":""},{"key":"sau","label":"Selling and admin per unit","unit":"money","f":"selling/units","x":""},{"key":"full","label":"Full cost per unit","unit":"money","f":"production+sau","x":""},{"key":"price","label":"Price for the profit wanted","unit":"money","f":"full/(1-margin/100)","x":""},{"key":"profit","label":"Profit per unit","unit":"money","f":"price-full","x":""}],"out":["full","price","profit"],"checks":[{"label":"Margin below 100 percent","f":"margin<100"},{"label":"Profit is the wanted share of price","f":"ABS(profit/price*100-margin)<0.0001"}],"notes":[]},{"id":"landed-cost","name":"Landed cost of an imported item","fn":"Costing","sectors":["Retail and e-commerce","Manufacturing","Electronics and semiconductor","Logistics and supply chain","Agriculture and food","Mining and metals"],"kw":["landed","cost","import","duty","freight","insurance","customs","clearance","procurement","sourcing"],"about":"Adds freight, insurance, duty and handling to the purchase price to show what an imported item really costs.","process":["Cost, insurance and freight value = goods price + freight + insurance.","Duty is charged on that value.","Add clearing and local handling to reach the landed cost per unit."],"inputs":[{"key":"price","label":"Goods price (all units)","unit":"money","sample":"500000"},{"key":"freight","label":"Freight","unit":"money","sample":"40000"},{"key":"insurance","label":"Insurance","unit":"money","sample":"3000"},{"key":"duty","label":"Duty rate","unit":"%","sample":"10"},{"key":"other","label":"Clearing and local handling","unit":"money","sample":"25000"},{"key":"units","label":"Number of units","unit":"units","sample":"1000"}],"steps":[{"key":"cif","label":"Goods + freight + insurance","unit":"money","f":"price+freight+insurance","x":""},{"key":"dutyamt","label":"Duty","unit":"money","f":"cif*duty/100","x":""},{"key":"landed","label":"Total landed cost","unit":"money","f":"cif+dutyamt+other","x":""},{"key":"perunit","label":"Landed cost per unit","unit":"money","f":"landed/units","x":""},{"key":"uplift","label":"Landed cost above goods price","unit":"%","f":"(landed/price-1)*100","x":""}],"out":["landed","perunit","uplift"],"checks":[{"label":"Landed cost not below goods price","f":"landed>=price"}],"notes":["Duty and other taxes follow your country's rules; enter the rate that applies."]},{"id":"make-or-buy","name":"Make or buy","fn":"Costing","sectors":["Manufacturing","Electronics and semiconductor","Technology and services","Agriculture and food","Construction and real estate"],"kw":["make","buy","outsource","insource","decision","relevant","cost"],"about":"Compares the avoidable cost of making an item in-house with the price of buying it.","process":["Add only the costs that disappear if you stop making it.","Compare with the price to buy."],"inputs":[{"key":"units","label":"Units needed per year","unit":"units","sample":"20000"},{"key":"material","label":"Material per unit","unit":"money","sample":"62"},{"key":"labour","label":"Labour per unit","unit":"money","sample":"28"},{"key":"varoh","label":"Variable overhead per unit","unit":"money","sample":"10"},{"key":"fixedsave","label":"Fixed cost that would be saved","unit":"money","sample":"150000"},{"key":"buy","label":"Price to buy per unit","unit":"money","sample":"105"}],"steps":[{"key":"makecost","label":"Avoidable cost of making (total)","unit":"money","f":"units*(material+labour+varoh)+fixedsave","x":""},{"key":"buycost","label":"Cost of buying (total)","unit":"money","f":"units*buy","x":""},{"key":"diff","label":"Making costs less by","unit":"money","f":"buycost-makecost","x":""},{"key":"choice","label":"Better choice (1 make, 0 buy)","unit":"flag","f":"IF(makecost<buycost,1,0)","x":""}],"out":["makecost","buycost","diff","choice"],"checks":[{"label":"Totals above zero","f":"AND(makecost>0,buycost>0)"}],"notes":["Look also at quality, delivery risk and what else the capacity could be used for."]},{"id":"overhead-rate","name":"Overhead absorption rate","fn":"Costing","sectors":["Manufacturing","Electronics and semiconductor","Agriculture and food","Healthcare","Education and training"],"kw":["overhead","absorption","rate","machine","hours","labour","hours","allocate","cost","centre"],"about":"Gives the overhead charged to each hour of work so every job carries its fair share.","process":["Add up the overhead of the cost centre.","Divide by the hours it will work.","Multiply by hours a job uses."],"inputs":[{"key":"overhead","label":"Overhead for the period","unit":"money","sample":"840000"},{"key":"hours","label":"Hours the centre will work","unit":"hours","sample":"4200"},{"key":"jobhours","label":"Hours used by this job","unit":"hours","sample":"36"}],"steps":[{"key":"rate","label":"Overhead per hour","unit":"money","f":"overhead/hours","x":""},{"key":"charge","label":"Overhead charged to this job","unit":"money","f":"rate*jobhours","x":""}],"out":["rate","charge"],"checks":[{"label":"Job hours not above centre hours","f":"jobhours<=hours"}],"notes":[]},{"id":"bcr","name":"Cost-benefit ratio for a public or social project","fn":"Economics","sectors":["Public sector and social enterprise","Education and training","Healthcare","Construction and real estate","Energy and utilities","Agriculture and food"],"kw":["cost","benefit","ratio","bcr","social","project","public","appraisal"],"about":"Compares the present value of benefits with the present value of costs.","process":["Discount the yearly benefits and the yearly costs at the social discount rate.","Divide benefits by costs."],"inputs":[{"key":"rate","label":"Discount rate","unit":"%","sample":"8"},{"key":"benefits","label":"Benefits per year, year 1 first","unit":"series","sample":"0,400000,600000,800000,800000,800000"},{"key":"costs","label":"Costs per year, year 1 first","unit":"series","sample":"900000,100000,100000,100000,100000,100000"}],"steps":[{"key":"pvb","label":"Present value of benefits","unit":"money","f":"NPV(rate/100,benefits)","x":""},{"key":"pvc","label":"Present value of costs","unit":"money","f":"NPV(rate/100,costs)","x":""},{"key":"bcr","label":"Benefit-cost ratio","unit":"times","f":"pvb/pvc","x":""},{"key":"net","label":"Net present benefit","unit":"money","f":"pvb-pvc","x":""}],"out":["bcr","net"],"checks":[{"label":"Both series cover the same years","f":"LEN(benefits)=LEN(costs)"}],"notes":["Count only benefits that can be measured and costs that are real. Describe the rest in words."]},{"id":"elasticity","name":"Price elasticity of demand","fn":"Economics","sectors":["Retail and e-commerce","Technology and services","Hospitality and travel","Agriculture and food","Manufacturing","Telecom and media"],"kw":["elasticity","price","demand","sensitivity","quantity","change","revenue"],"about":"Shows how much sales change when price changes, and whether a price rise lifts or cuts revenue.","process":["Percent change in quantity divided by percent change in price (midpoint method).","If the size is above 1, demand is sensitive to price."],"inputs":[{"key":"p1","label":"Old price","unit":"money","sample":"100"},{"key":"p2","label":"New price","unit":"money","sample":"110"},{"key":"q1","label":"Old quantity","unit":"units","sample":"5000"},{"key":"q2","label":"New quantity","unit":"units","sample":"4700"}],"steps":[{"key":"dq","label":"Change in quantity (midpoint)","unit":"%","f":"(q2-q1)/((q1+q2)/2)*100","x":""},{"key":"dp","label":"Change in price (midpoint)","unit":"%","f":"(p2-p1)/((p1+p2)/2)*100","x":""},{"key":"e","label":"Elasticity","unit":"ratio","f":"dq/dp","x":""},{"key":"size","label":"Size of elasticity","unit":"ratio","f":"ABS(e)","x":""},{"key":"rev1","label":"Revenue before","unit":"money","f":"p1*q1","x":""},{"key":"rev2","label":"Revenue after","unit":"money","f":"p2*q2","x":""},{"key":"sens","label":"Demand is sensitive to price (1 yes, 0 no)","unit":"flag","f":"IF(size>1,1,0)","x":""}],"out":["e","sens","rev1","rev2"],"checks":[{"label":"Revenue moves the way elasticity says","f":"IF(sens=1,(rev2-rev1)*(p2-p1)<=0,(rev2-rev1)*(p2-p1)>=0)=1"}],"notes":["Teaching sample uses invented figures."]},{"id":"market-equilibrium","name":"Supply and demand equilibrium","fn":"Economics","sectors":["*"],"kw":["supply","demand","equilibrium","price","quantity","market","linear"],"about":"Finds the price at which demand and supply are equal for straight-line curves.","process":["Demand: quantity = a - b x price. Supply: quantity = c + d x price.","Set them equal and solve for price."],"inputs":[{"key":"a","label":"Demand when price is zero (a)","unit":"units","sample":"1000"},{"key":"b","label":"Demand drop per unit of price (b)","unit":"units","sample":"4"},{"key":"c","label":"Supply when price is zero (c)","unit":"units","sample":"100"},{"key":"d","label":"Supply rise per unit of price (d)","unit":"units","sample":"6"}],"steps":[{"key":"price","label":"Equilibrium price","unit":"money","f":"(a-c)/(b+d)","x":""},{"key":"qty","label":"Equilibrium quantity","unit":"units","f":"a-b*price","x":""},{"key":"supplycheck","label":"Quantity from the supply line","unit":"units","f":"c+d*price","x":""}],"out":["price","qty"],"checks":[{"label":"Both lines give the same quantity","f":"ABS(qty-supplycheck)<0.0001"},{"label":"Slopes are positive","f":"AND(b>0,d>0)"}],"notes":[]},{"id":"inflation-adjust","name":"Inflation adjustment (price today vs then)","fn":"Economics","sectors":["*"],"kw":["inflation","adjust","purchasing","power","escalation","index","price","revision"],"about":"Converts an amount between years using the change in a price index.","process":["Divide the index of the target year by the index of the base year.","Multiply the amount by that ratio."],"inputs":[{"key":"amount","label":"Amount in base year","unit":"money","sample":"100000"},{"key":"base","label":"Index in base year","unit":"index","sample":"120"},{"key":"target","label":"Index in target year","unit":"index","sample":"152"}],"steps":[{"key":"factor","label":"Adjustment factor","unit":"ratio","f":"target/base","x":""},{"key":"adjusted","label":"Amount in target-year prices","unit":"money","f":"amount*factor","x":""},{"key":"rate","label":"Average yearly rate if 5 years apart","unit":"%","f":"(POW(factor,1/5)-1)*100","x":""}],"out":["adjusted","factor"],"checks":[{"label":"Factor is above zero","f":"factor>0"}],"notes":[]},{"id":"risk-register","name":"Risk score and expected loss","fn":"Risk review","sectors":["*"],"kw":["risk","register","likelihood","impact","score","matrix","expected","loss","heat","map","assessment","review"],"about":"Scores each risk by chance and impact and adds up the expected loss.","process":["Give each risk a chance (0 to 1) and a money impact.","Expected loss is chance times impact.","Large impact with low chance and small impact with high chance are both visible."],"inputs":[{"key":"probs","label":"Chance of each risk (0 to 1)","unit":"series","sample":"0.1,0.3,0.05,0.5"},{"key":"impacts","label":"Impact of each risk if it happens","unit":"series","sample":"800000,150000,2000000,60000"}],"steps":[{"key":"el","label":"Expected loss per risk","unit":"series","f":"probs*impacts","x":""},{"key":"total","label":"Total expected loss","unit":"money","f":"SUM(el)","x":""},{"key":"worst","label":"Largest single impact","unit":"money","f":"MAX(impacts)","x":""},{"key":"top","label":"Largest expected loss of one risk","unit":"money","f":"MAX(el)","x":""}],"out":["total","worst","top"],"checks":[{"label":"Chances are between 0 and 1","f":"AND(MIN(probs)>=0,MAX(probs)<=1)"},{"label":"Same number of chances and impacts","f":"LEN(probs)=LEN(impacts)"}],"notes":[]},{"id":"var","name":"Value at risk","fn":"Risk review","sectors":["Banking and insurance","Technology and services","Energy and utilities","Agriculture and food","Mining and metals","Retail and e-commerce"],"kw":["var","value","at","risk","volatility","confidence","portfolio","loss","treasury","market","risk"],"about":"Estimates the loss that should not be exceeded on all but the worst few days, using the normal curve.","process":["Convert the yearly volatility to the holding period.","Multiply by the value and by the confidence factor from the normal curve."],"inputs":[{"key":"value","label":"Value held","unit":"money","sample":"5000000"},{"key":"vol","label":"Yearly volatility","unit":"%","sample":"18"},{"key":"days","label":"Holding period","unit":"days","sample":"10"},{"key":"conf","label":"Confidence","unit":"%","sample":"95"}],"steps":[{"key":"z","label":"Confidence factor","unit":"ratio","f":"NORMSINV(conf/100)","x":""},{"key":"volp","label":"Volatility over the holding period","unit":"%","f":"vol*SQRT(days/250)","x":""},{"key":"var","label":"Value at risk","unit":"money","f":"value*volp/100*z","x":""},{"key":"share","label":"As share of value","unit":"%","f":"var/value*100","x":""}],"out":["var","share"],"checks":[{"label":"Confidence between 50 and 100","f":"AND(conf>50,conf<100)"}],"notes":["Normal-curve estimate. Real losses can be larger in a crisis; use stress tests alongside it."]},{"id":"scenario-weight","name":"Scenario-weighted outcome","fn":"Risk review","sectors":["*"],"kw":["scenario","best","worst","base","probability","weighted","expected","value","sensitivity","stress"],"about":"Combines best, base and worst cases using the chance you give each.","process":["Give each scenario a value and a chance.","Expected value is the chance-weighted average; spread shows how uncertain it is."],"inputs":[{"key":"v","label":"Value in each scenario","unit":"series","sample":"1200000,900000,300000"},{"key":"p","label":"Chance of each scenario","unit":"series","sample":"0.25,0.5,0.25"}],"steps":[{"key":"ev","label":"Expected value","unit":"money","f":"SUMPRODUCT(v,p)","x":""},{"key":"dev","label":"Squared distance from expected","unit":"series","f":"(v-ev)^2","x":""},{"key":"spread","label":"Spread (standard deviation)","unit":"money","f":"SQRT(SUMPRODUCT(dev,p))","x":""},{"key":"worstcase","label":"Worst case","unit":"money","f":"MIN(v)","x":""}],"out":["ev","spread","worstcase"],"checks":[{"label":"Chances add to one","f":"ABS(SUM(p)-1)<0.000001"}],"notes":[]},{"id":"z-score","name":"Distress score for manufacturers (Z-score)","fn":"Risk review","sectors":["Manufacturing","Electronics and semiconductor","Energy and utilities","Mining and metals","Agriculture and food"],"kw":["z","score","bankruptcy","distress","credit","default","solvency","early","warning"],"about":"Combines five ratios into one early-warning score for manufacturing companies.","process":["Compute five ratios from the balance sheet and profit statement.","Weight and add them. Above 2.99 is usually safe, below 1.81 is a warning."],"inputs":[{"key":"wc","label":"Working capital","unit":"money","sample":"1500000"},{"key":"re","label":"Retained earnings","unit":"money","sample":"2200000"},{"key":"ebit","label":"Operating profit","unit":"money","sample":"1100000"},{"key":"mve","label":"Market (or fair) value of equity","unit":"money","sample":"6000000"},{"key":"sales","label":"Sales","unit":"money","sample":"12000000"},{"key":"ta","label":"Total assets","unit":"money","sample":"9500000"},{"key":"tl","label":"Total liabilities","unit":"money","sample":"5200000"}],"steps":[{"key":"x1","label":"Working capital / assets","unit":"ratio","f":"wc/ta","x":""},{"key":"x2","label":"Retained earnings / assets","unit":"ratio","f":"re/ta","x":""},{"key":"x3","label":"Operating profit / assets","unit":"ratio","f":"ebit/ta","x":""},{"key":"x4","label":"Equity value / liabilities","unit":"ratio","f":"mve/tl","x":""},{"key":"x5","label":"Sales / assets","unit":"ratio","f":"sales/ta","x":""},{"key":"z","label":"Z-score","unit":"score","f":"1.2*x1+1.4*x2+3.3*x3+0.6*x4+1.0*x5","x":""},{"key":"zone","label":"Zone (3 safe, 2 grey, 1 warning)","unit":"flag","f":"IF(z>2.99,3,IF(z>1.81,2,1))","x":""}],"out":["z","zone"],"checks":[{"label":"Assets above zero","f":"ta>0"}],"notes":["Published for listed manufacturers; use as a prompt for questions, not as a verdict."]},{"id":"sensitivity","name":"Sensitivity of profit to price, volume and cost","fn":"Risk review","sectors":["*"],"kw":["sensitivity","what","if","tornado","profit","price","volume","cost","change","test"],"about":"Shows how much profit moves when price, volume or cost changes by the same percent.","process":["Work out base profit.","Change each driver by the chosen percent, one at a time, and see profit."],"inputs":[{"key":"price","label":"Price per unit","unit":"money","sample":"450"},{"key":"units","label":"Units sold","unit":"units","sample":"6500"},{"key":"vc","label":"Variable cost per unit","unit":"money","sample":"270"},{"key":"fixed","label":"Fixed costs","unit":"money","sample":"900000"},{"key":"change","label":"Change to test","unit":"%","sample":"10"}],"steps":[{"key":"base","label":"Base profit","unit":"money","f":"units*(price-vc)-fixed","x":""},{"key":"pup","label":"Profit if price rises","unit":"money","f":"units*(price*(1+change/100)-vc)-fixed","x":""},{"key":"pdown","label":"Profit if price falls","unit":"money","f":"units*(price*(1-change/100)-vc)-fixed","x":""},{"key":"vup","label":"Profit if volume rises","unit":"money","f":"units*(1+change/100)*(price-vc)-fixed","x":""},{"key":"vdown","label":"Profit if volume falls","unit":"money","f":"units*(1-change/100)*(price-vc)-fixed","x":""},{"key":"cup","label":"Profit if variable cost rises","unit":"money","f":"units*(price-vc*(1+change/100))-fixed","x":""},{"key":"cdown","label":"Profit if variable cost falls","unit":"money","f":"units*(price-vc*(1-change/100))-fixed","x":""},{"key":"swingp","label":"Price swing in profit","unit":"money","f":"pup-pdown","x":""},{"key":"swingv","label":"Volume swing in profit","unit":"money","f":"vup-vdown","x":""},{"key":"swingc","label":"Cost swing in profit","unit":"money","f":"cdown-cup","x":""}],"out":["base","swingp","swingv","swingc"],"checks":[{"label":"Price is the most sensitive driver when price is above cost","f":"IF(price>vc,swingp>=swingv,1)=1"}],"notes":[]},{"id":"three-phase","name":"Three-phase electrical load","fn":"Engineering","sectors":["Manufacturing","Electronics and semiconductor","Energy and utilities","Construction and real estate","Healthcare","Telecom and media","Hospitality and travel"],"kw":["three","phase","current","load","kw","kva","power","factor","motor","electrical","supply"],"about":"Finds the current and apparent power drawn by a three-phase load.","process":["Real power in kW divided by efficiency and power factor gives apparent power in kVA.","Current = kVA x 1000 / (root three x voltage)."],"inputs":[{"key":"kw","label":"Load at the shaft or output","unit":"kW","sample":"75"},{"key":"v","label":"Line voltage","unit":"volts","sample":"415"},{"key":"pf","label":"Power factor","unit":"ratio","sample":"0.85"},{"key":"eff","label":"Efficiency","unit":"%","sample":"92"}],"steps":[{"key":"input","label":"Electrical input power","unit":"kW","f":"kw/(eff/100)","x":""},{"key":"kva","label":"Apparent power","unit":"kVA","f":"input/pf","x":""},{"key":"amps","label":"Line current","unit":"amps","f":"kva*1000/(SQRT(3)*v)","x":""},{"key":"kvar","label":"Reactive power","unit":"kVAr","f":"SQRT(kva^2-input^2)","x":""}],"out":["input","kva","amps","kvar"],"checks":[{"label":"Power factor between 0 and 1","f":"AND(pf>0,pf<=1)"},{"label":"kVA squared equals kW squared plus kVAr squared","f":"ABS(kva^2-(input^2+kvar^2))<0.001*kva^2"}],"notes":["For cable sizing, protection and earthing use the detailed electrical calculators on this platform."]},{"id":"voltage-drop","name":"Cable voltage drop","fn":"Engineering","sectors":["Manufacturing","Electronics and semiconductor","Energy and utilities","Construction and real estate","Healthcare","Telecom and media"],"kw":["voltage","drop","cable","length","resistance","reactance","feeder","electrical"],"about":"Estimates the percentage voltage lost along a three-phase cable.","process":["Use the cable's resistance and reactance per kilometre.","Drop = root three x current x length x (R x pf + X x sin angle)."],"inputs":[{"key":"amps","label":"Load current","unit":"amps","sample":"120"},{"key":"km","label":"Cable length","unit":"km","sample":"0.15"},{"key":"r","label":"Resistance","unit":"ohm per km","sample":"0.32"},{"key":"x","label":"Reactance","unit":"ohm per km","sample":"0.08"},{"key":"pf","label":"Power factor","unit":"ratio","sample":"0.85"},{"key":"v","label":"Line voltage","unit":"volts","sample":"415"}],"steps":[{"key":"sinphi","label":"Sine of the power-factor angle","unit":"ratio","f":"SQRT(1-pf^2)","x":""},{"key":"dv","label":"Voltage drop","unit":"volts","f":"SQRT(3)*amps*km*(r*pf+x*sinphi)","x":""},{"key":"pct","label":"Voltage drop","unit":"%","f":"dv/v*100","x":""},{"key":"ok","label":"Within 5 percent (1 yes, 0 no)","unit":"flag","f":"IF(pct<=5,1,0)","x":""}],"out":["dv","pct","ok"],"checks":[{"label":"Drop is not negative","f":"dv>=0"}],"notes":["The 5 percent limit is a common design aim; use the limit in your own standard."]},{"id":"beam-udl","name":"Simply supported beam under even load","fn":"Engineering","sectors":["Construction and real estate","Manufacturing","Mining and metals","Energy and utilities"],"kw":["beam","bending","moment","deflection","span","load","structural","steel","simply","supported"],"about":"Finds the largest bending moment, reaction and mid-span deflection of a beam carrying an evenly spread load.","process":["Moment = w L squared / 8. Reaction = w L / 2.","Deflection = 5 w L to the power 4 / (384 E I)."],"inputs":[{"key":"w","label":"Even load","unit":"kN per m","sample":"10"},{"key":"l","label":"Span","unit":"m","sample":"5"},{"key":"e","label":"Modulus of elasticity","unit":"GPa","sample":"200"},{"key":"i","label":"Second moment of area","unit":"cm4","sample":"8000"}],"steps":[{"key":"m","label":"Largest bending moment","unit":"kN m","f":"w*l^2/8","x":""},{"key":"r","label":"Reaction at each support","unit":"kN","f":"w*l/2","x":""},{"key":"ei","label":"Bending stiffness EI","unit":"kN m2","f":"e*i*0.01","x":""},{"key":"defl","label":"Deflection at mid-span","unit":"mm","f":"5*w*l^4/(384*ei)*1000","x":""},{"key":"ratio","label":"Span divided by deflection","unit":"ratio","f":"l*1000/defl","x":""}],"out":["m","r","defl","ratio"],"checks":[{"label":"Moment equals reaction times half span less load on half span","f":"ABS(m-(r*l/2-w*l/2*l/4))<0.0001"}],"notes":["Check against the limits in your design code. Span/deflection of 250 to 360 is typical."]},{"id":"pump-power","name":"Pump power","fn":"Engineering","sectors":["Manufacturing","Energy and utilities","Agriculture and food","Construction and real estate","Mining and metals","Healthcare"],"kw":["pump","power","flow","head","hydraulic","efficiency","motor","water","kw"],"about":"Finds the power needed to lift a flow of water to a given head.","process":["Hydraulic power = 9.81 x flow (m3/h) x head / 3600.","Divide by pump efficiency for shaft power, and by motor efficiency for electrical power."],"inputs":[{"key":"q","label":"Flow","unit":"m3 per hour","sample":"120"},{"key":"h","label":"Head (lift plus losses)","unit":"m","sample":"35"},{"key":"pe","label":"Pump efficiency","unit":"%","sample":"70"},{"key":"me","label":"Motor efficiency","unit":"%","sample":"92"}],"steps":[{"key":"hyd","label":"Hydraulic power","unit":"kW","f":"9.81*q*h/3600","x":""},{"key":"shaft","label":"Shaft power","unit":"kW","f":"hyd/(pe/100)","x":""},{"key":"elec","label":"Electrical input","unit":"kW","f":"shaft/(me/100)","x":""}],"out":["hyd","shaft","elec"],"checks":[{"label":"Electrical input at least hydraulic power","f":"elec>=hyd"}],"notes":["Water at normal temperature assumed (density 1000 kg per m3)."]},{"id":"heat-conduction","name":"Heat through a wall","fn":"Engineering","sectors":["Construction and real estate","Manufacturing","Energy and utilities","Electronics and semiconductor","Healthcare"],"kw":["heat","conduction","wall","insulation","thermal","u","value","thickness","loss"],"about":"Finds heat flow through a flat wall from its material, area and temperature difference.","process":["Heat flow = k x area x temperature difference / thickness."],"inputs":[{"key":"k","label":"Conductivity","unit":"W per m K","sample":"0.04"},{"key":"area","label":"Area","unit":"m2","sample":"120"},{"key":"t1","label":"Inside temperature","unit":"deg C","sample":"22"},{"key":"t2","label":"Outside temperature","unit":"deg C","sample":"4"},{"key":"d","label":"Thickness","unit":"m","sample":"0.1"}],"steps":[{"key":"dt","label":"Temperature difference","unit":"K","f":"t1-t2","x":""},{"key":"q","label":"Heat flow","unit":"W","f":"k*area*dt/d","x":""},{"key":"u","label":"U-value","unit":"W per m2 K","f":"k/d","x":""},{"key":"kwh","label":"Energy lost over a day","unit":"kWh","f":"q*24/1000","x":""}],"out":["q","u","kwh"],"checks":[{"label":"Heat flow follows the U-value","f":"ABS(q-u*area*dt)<0.0001"}],"notes":[]},{"id":"solar-yield","name":"Solar plant yearly energy","fn":"Engineering","sectors":["Energy and utilities","Agriculture and food","Manufacturing","Construction and real estate","Healthcare","Education and training","Hospitality and travel"],"kw":["solar","pv","yield","kwp","energy","generation","performance","ratio","sun","hours","renewable"],"about":"Estimates the energy a solar array produces in a year and its value.","process":["Capacity x sun hours per day x 365 x performance ratio.","Multiply by the price of energy for the value."],"inputs":[{"key":"kwp","label":"Plant size","unit":"kWp","sample":"100"},{"key":"sun","label":"Peak sun hours per day","unit":"hours","sample":"5.2"},{"key":"pr","label":"Performance ratio","unit":"%","sample":"78"},{"key":"tariff","label":"Value of energy","unit":"money per kWh","sample":"7"},{"key":"degr","label":"Yearly loss of output","unit":"%","sample":"0.6"}],"steps":[{"key":"y1","label":"Energy in year 1","unit":"kWh","f":"kwp*sun*365*pr/100","x":""},{"key":"value","label":"Value in year 1","unit":"money","f":"y1*tariff","x":""},{"key":"y10","label":"Energy in year 10","unit":"kWh","f":"y1*POW(1-degr/100,9)","x":""},{"key":"cuf","label":"Capacity use factor","unit":"%","f":"y1/(kwp*8760)*100","x":""}],"out":["y1","value","y10","cuf"],"checks":[{"label":"Capacity use factor between 5 and 35 percent is usual","f":"AND(cuf>5,cuf<35)"}],"notes":["Use measured sun-hours for your place and season; the sample is only an example."]},{"id":"lcoe","name":"Cost of each unit of energy over a plant's life","fn":"Engineering","sectors":["Energy and utilities","Manufacturing","Public sector and social enterprise","Agriculture and food"],"kw":["lcoe","levelised","cost","of","energy","electricity","generation","capex","capital","recovery"],"about":"Spreads the cost of building and running a plant over the energy it produces.","process":["Convert the build cost into a yearly charge using the capital recovery factor.","Add yearly running cost; divide by yearly energy."],"inputs":[{"key":"capex","label":"Build cost","unit":"money","sample":"5000000"},{"key":"om","label":"Running cost per year","unit":"money","sample":"80000"},{"key":"kwh","label":"Energy per year","unit":"kWh","sample":"1750000"},{"key":"rate","label":"Discount rate","unit":"%","sample":"10"},{"key":"life","label":"Plant life","unit":"years","sample":"25"}],"steps":[{"key":"crf","label":"Capital recovery factor","unit":"ratio","f":"(rate/100)*POW(1+rate/100,life)/(POW(1+rate/100,life)-1)","x":""},{"key":"annual","label":"Yearly cost","unit":"money","f":"capex*crf+om","x":""},{"key":"lcoe","label":"Cost per kWh","unit":"money","f":"annual/kwh","x":""}],"out":["crf","annual","lcoe"],"checks":[{"label":"Recovering the yearly charge repays the build cost","f":"ABS(PV(rate/100,life,capex*crf)-capex)<0.01*capex/1000"}],"notes":["Add fuel, tax and degradation if they apply."]},{"id":"die-yield","name":"Chips per wafer and yield","fn":"Engineering","sectors":["Electronics and semiconductor"],"kw":["die","yield","wafer","defect","density","semiconductor","chip","dies","per","wafer","poisson","fab"],"about":"Estimates good chips per wafer from chip size and defect density.","process":["Gross dies from wafer area and chip area, less edge losses.","Yield falls with chip area and defect density (Poisson model)."],"inputs":[{"key":"dia","label":"Wafer diameter","unit":"mm","sample":"300"},{"key":"w","label":"Chip width","unit":"mm","sample":"8"},{"key":"h","label":"Chip height","unit":"mm","sample":"8"},{"key":"d0","label":"Defects","unit":"per cm2","sample":"0.1"}],"steps":[{"key":"area","label":"Chip area","unit":"mm2","f":"w*h","x":""},{"key":"gross","label":"Gross chips per wafer","unit":"count","f":"FLOOR(PI*(dia/2)^2/area-PI*dia/SQRT(2*area))","x":""},{"key":"y","label":"Yield","unit":"%","f":"EXP(-d0*area/100)*100","x":""},{"key":"good","label":"Good chips per wafer","unit":"count","f":"FLOOR(gross*y/100)","x":""}],"out":["gross","y","good"],"checks":[{"label":"Yield between 0 and 100","f":"AND(y>0,y<=100)"},{"label":"Good chips do not exceed gross","f":"good<=gross"}],"notes":["Poisson model is the simplest; other models fit real factories better. Sample numbers are for teaching."]},{"id":"pcb-panel","name":"Boards per production panel","fn":"Engineering","sectors":["Electronics and semiconductor"],"kw":["pcb","panel","utilisation","boards","per","panel","layout","array","hdi","board"],"about":"Counts how many boards fit on a production panel and how much material is used.","process":["Each board plus the gap between boards takes a slot.","Count slots along each side; multiply."],"inputs":[{"key":"pl","label":"Panel length","unit":"mm","sample":"450"},{"key":"pw","label":"Panel width","unit":"mm","sample":"350"},{"key":"bl","label":"Board length","unit":"mm","sample":"60"},{"key":"bw","label":"Board width","unit":"mm","sample":"45"},{"key":"gap","label":"Gap between boards","unit":"mm","sample":"4"},{"key":"border","label":"Unused border on every side","unit":"mm","sample":"10"}],"steps":[{"key":"nl","label":"Boards along length","unit":"count","f":"FLOOR((pl-2*border+gap)/(bl+gap))","x":""},{"key":"nw","label":"Boards along width","unit":"count","f":"FLOOR((pw-2*border+gap)/(bw+gap))","x":""},{"key":"n","label":"Boards per panel","unit":"count","f":"nl*nw","x":""},{"key":"use","label":"Panel area used by boards","unit":"%","f":"n*bl*bw/(pl*pw)*100","x":""}],"out":["n","use"],"checks":[{"label":"Boards fit on the panel","f":"n*bl*bw<=pl*pw"}],"notes":[]},{"id":"battery-backup","name":"Battery backup size","fn":"Engineering","sectors":["Energy and utilities","Telecom and media","Healthcare","Technology and services","Manufacturing","Hospitality and travel"],"kw":["battery","backup","ups","storage","kwh","autonomy","depth","of","discharge","inverter","capacity"],"about":"Sizes a battery bank for a load that must run for a number of hours.","process":["Energy = load x hours.","Divide by inverter efficiency and the usable share of the battery."],"inputs":[{"key":"load","label":"Load","unit":"kW","sample":"12"},{"key":"hours","label":"Backup time","unit":"hours","sample":"4"},{"key":"dod","label":"Usable share (depth of discharge)","unit":"%","sample":"80"},{"key":"eff","label":"Inverter efficiency","unit":"%","sample":"92"}],"steps":[{"key":"need","label":"Energy to deliver","unit":"kWh","f":"load*hours","x":""},{"key":"cap","label":"Battery size to install","unit":"kWh","f":"need/(dod/100)/(eff/100)","x":""},{"key":"margin","label":"Extra capacity over need","unit":"%","f":"(cap/need-1)*100","x":""}],"out":["need","cap"],"checks":[{"label":"Battery larger than energy to deliver","f":"cap>=need"}],"notes":[]},{"id":"eoq","name":"Order quantity and reorder point","fn":"Operations","sectors":["Retail and e-commerce","Manufacturing","Healthcare","Agriculture and food","Logistics and supply chain","Hospitality and travel","Electronics and semiconductor"],"kw":["eoq","economic","order","quantity","reorder","point","safety","stock","inventory","holding","ordering","lead","time"],"about":"Finds the order size that balances ordering cost and holding cost, and when to reorder.","process":["EOQ = square root of (2 x yearly demand x cost per order / holding cost per unit per year).","Reorder point = demand during lead time + safety stock."],"inputs":[{"key":"demand","label":"Yearly demand","unit":"units","sample":"12000"},{"key":"order","label":"Cost to place one order","unit":"money","sample":"800"},{"key":"hold","label":"Holding cost per unit per year","unit":"money","sample":"24"},{"key":"lead","label":"Lead time","unit":"days","sample":"10"},{"key":"sd","label":"Daily demand variation (standard deviation)","unit":"units","sample":"8"},{"key":"service","label":"Service level wanted","unit":"%","sample":"95"}],"steps":[{"key":"eoq","label":"Order quantity","unit":"units","f":"SQRT(2*demand*order/hold)","x":""},{"key":"orders","label":"Orders per year","unit":"count","f":"demand/eoq","x":""},{"key":"cost","label":"Yearly ordering plus holding cost","unit":"money","f":"orders*order+eoq/2*hold","x":""},{"key":"daily","label":"Demand per day","unit":"units","f":"demand/365","x":""},{"key":"safety","label":"Safety stock","unit":"units","f":"NORMSINV(service/100)*sd*SQRT(lead)","x":""},{"key":"rop","label":"Reorder point","unit":"units","f":"daily*lead+safety","x":""}],"out":["eoq","orders","cost","safety","rop"],"checks":[{"label":"At EOQ ordering cost equals holding cost","f":"ABS(orders*order-eoq/2*hold)<0.001*cost"}],"notes":[]},{"id":"oee","name":"Overall equipment effectiveness (OEE)","fn":"Operations","sectors":["Manufacturing","Electronics and semiconductor","Agriculture and food","Mining and metals","Energy and utilities"],"kw":["oee","equipment","effectiveness","availability","performance","quality","downtime","machine","line","plant"],"about":"Combines downtime, speed and quality losses into one score for a machine or line.","process":["Availability = run time / planned time.","Performance = actual output / output at ideal speed.","Quality = good units / all units. Multiply the three."],"inputs":[{"key":"planned","label":"Planned production time","unit":"minutes","sample":"480"},{"key":"down","label":"Downtime","unit":"minutes","sample":"55"},{"key":"ideal","label":"Ideal cycle time per unit","unit":"minutes","sample":"0.5"},{"key":"total","label":"Units produced","unit":"units","sample":"780"},{"key":"good","label":"Good units","unit":"units","sample":"748"}],"steps":[{"key":"run","label":"Run time","unit":"minutes","f":"planned-down","x":""},{"key":"av","label":"Availability","unit":"%","f":"run/planned*100","x":""},{"key":"pf","label":"Performance","unit":"%","f":"ideal*total/run*100","x":""},{"key":"ql","label":"Quality","unit":"%","f":"good/total*100","x":""},{"key":"oee","label":"OEE","unit":"%","f":"av*pf*ql/10000","x":""}],"out":["av","pf","ql","oee"],"checks":[{"label":"Good units not above units produced","f":"good<=total"},{"label":"Performance not above 100 percent","f":"pf<=100.0001"}],"notes":["Above 85 percent is usually called world class for discrete making."]},{"id":"takt-time","name":"Takt time and workers needed","fn":"Operations","sectors":["Manufacturing","Electronics and semiconductor","Agriculture and food","Healthcare","Hospitality and travel"],"kw":["takt","time","demand","pace","line","balancing","workers","cycle"],"about":"Gives the pace at which a unit must be finished to meet customer demand.","process":["Takt time = available time / demand.","Workers needed = total work content / takt time."],"inputs":[{"key":"avail","label":"Available time per day","unit":"minutes","sample":"450"},{"key":"demand","label":"Demand per day","unit":"units","sample":"300"},{"key":"work","label":"Total work content per unit","unit":"minutes","sample":"4.2"}],"steps":[{"key":"takt","label":"Takt time","unit":"minutes","f":"avail/demand","x":""},{"key":"workers","label":"Workers needed (exact)","unit":"count","f":"work/takt","x":""},{"key":"whole","label":"Workers needed (whole)","unit":"count","f":"CEIL(workers)","x":""}],"out":["takt","workers","whole"],"checks":[{"label":"Whole workers are enough","f":"whole*takt>=work"}],"notes":[]},{"id":"sigma","name":"Defects per million and sigma level","fn":"Operations","sectors":["Manufacturing","Electronics and semiconductor","Healthcare","Technology and services","Banking and insurance","Logistics and supply chain"],"kw":["sigma","dpmo","defects","quality","six","sigma","process","level","yield"],"about":"Converts counts of defects into defects per million and a sigma level.","process":["DPMO = defects / (units x chances per unit) x one million.","Sigma level = normal-curve value of the yield, plus the usual 1.5 shift."],"inputs":[{"key":"defects","label":"Defects found","unit":"count","sample":"38"},{"key":"units","label":"Units checked","unit":"units","sample":"5000"},{"key":"opp","label":"Chances for a defect in each unit","unit":"count","sample":"4"}],"steps":[{"key":"dpmo","label":"Defects per million","unit":"count","f":"defects/(units*opp)*1000000","x":""},{"key":"yld","label":"Yield","unit":"%","f":"(1-dpmo/1000000)*100","x":""},{"key":"sig","label":"Sigma level","unit":"sigma","f":"NORMSINV(1-dpmo/1000000)+1.5","x":""}],"out":["dpmo","yld","sig"],"checks":[{"label":"Defects not more than chances","f":"defects<=units*opp"}],"notes":[]},{"id":"cpk","name":"Process capability (Cpk)","fn":"Operations","sectors":["Manufacturing","Electronics and semiconductor","Agriculture and food","Healthcare"],"kw":["cpk","process","capability","tolerance","specification","limits","mean","standard","deviation","quality"],"about":"Shows whether a process stays inside its specification limits.","process":["Cp = tolerance width / six standard deviations.","Cpk also looks at how far the average is from the nearer limit."],"inputs":[{"key":"lsl","label":"Lower limit","unit":"number","sample":"9.7"},{"key":"usl","label":"Upper limit","unit":"number","sample":"10.3"},{"key":"mean","label":"Process average","unit":"number","sample":"10.04"},{"key":"sd","label":"Standard deviation","unit":"number","sample":"0.07"}],"steps":[{"key":"cp","label":"Cp","unit":"ratio","f":"(usl-lsl)/(6*sd)","x":""},{"key":"cpu","label":"Upper side","unit":"ratio","f":"(usl-mean)/(3*sd)","x":""},{"key":"cpl","label":"Lower side","unit":"ratio","f":"(mean-lsl)/(3*sd)","x":""},{"key":"cpk","label":"Cpk","unit":"ratio","f":"MIN(cpu,cpl)","x":""},{"key":"ok","label":"Capable at 1.33 (1 yes, 0 no)","unit":"flag","f":"IF(cpk>=1.33,1,0)","x":""}],"out":["cp","cpk","ok"],"checks":[{"label":"Limits in order","f":"usl>lsl"},{"label":"Cpk not above Cp","f":"cpk<=cp+0.000001"}],"notes":[]},{"id":"learning-curve","name":"Learning curve: cost of the nth unit","fn":"Operations","sectors":["Manufacturing","Electronics and semiconductor","Construction and real estate","Technology and services"],"kw":["learning","curve","experience","cost","reduction","nth","unit","repetition","hours"],"about":"Shows how time or cost per unit falls as the same work is repeated.","process":["Each time output doubles, cost per unit falls to the learning rate.","Cost of unit n = first unit cost x n to the power of (ln rate / ln 2)."],"inputs":[{"key":"first","label":"Cost (or hours) of unit 1","unit":"money","sample":"1000"},{"key":"rate","label":"Learning rate (cost after doubling)","unit":"%","sample":"85"},{"key":"n","label":"Unit number","unit":"count","sample":"64"}],"steps":[{"key":"b","label":"Exponent","unit":"ratio","f":"LN(rate/100)/LN(2)","x":""},{"key":"cn","label":"Cost of unit n","unit":"money","f":"first*POW(n,b)","x":""},{"key":"fall","label":"Fall from unit 1","unit":"%","f":"(1-cn/first)*100","x":""}],"out":["cn","fall"],"checks":[{"label":"Unit 2 costs the learning rate times unit 1","f":"ABS(first*POW(2,b)-first*rate/100)<0.0001"}],"notes":[]},{"id":"queue","name":"Queue: waiting time at a counter or machine","fn":"Operations","sectors":["Retail and e-commerce","Healthcare","Banking and insurance","Technology and services","Telecom and media","Public sector and social enterprise","Hospitality and travel","Logistics and supply chain"],"kw":["queue","waiting","line","arrival","service","rate","utilisation","customers","helpdesk","counter","mm1"],"about":"Estimates waiting for a single server when arrivals are random.","process":["Utilisation = arrival rate / service rate.","Average wait in queue = utilisation / (service rate - arrival rate)."],"inputs":[{"key":"arr","label":"Arrivals per hour","unit":"count","sample":"8"},{"key":"svc","label":"Served per hour","unit":"count","sample":"10"}],"steps":[{"key":"rho","label":"Utilisation","unit":"%","f":"arr/svc*100","x":""},{"key":"lq","label":"Average number waiting","unit":"count","f":"(arr/svc)^2/(1-arr/svc)","x":""},{"key":"wq","label":"Average wait","unit":"minutes","f":"arr/(svc*(svc-arr))*60","x":""},{"key":"w","label":"Average time in system","unit":"minutes","f":"1/(svc-arr)*60","x":""}],"out":["rho","lq","wq","w"],"checks":[{"label":"Server keeps up with arrivals","f":"arr<svc"}],"notes":["Needs service faster than arrivals. Real queues with several servers or fixed times differ."]},{"id":"cac-ltv","name":"Customer acquisition cost and lifetime value","fn":"Sales and marketing","sectors":["Technology and services","Retail and e-commerce","Education and training","Telecom and media","Banking and insurance","Healthcare","Hospitality and travel"],"kw":["cac","ltv","customer","acquisition","cost","lifetime","value","churn","payback","subscription","marketing","saas"],"about":"Compares what it costs to win a customer with what the customer is worth.","process":["CAC = marketing and sales spend / new customers.","Customer lifetime = 1 / churn. LTV = margin per period x lifetime."],"inputs":[{"key":"spend","label":"Marketing and sales spend","unit":"money","sample":"600000"},{"key":"newc","label":"New customers won","unit":"count","sample":"400"},{"key":"arpa","label":"Revenue per customer per month","unit":"money","sample":"900"},{"key":"gm","label":"Gross margin","unit":"%","sample":"70"},{"key":"churn","label":"Monthly churn","unit":"%","sample":"3"}],"steps":[{"key":"cac","label":"Cost to win a customer","unit":"money","f":"spend/newc","x":""},{"key":"margin","label":"Margin per customer per month","unit":"money","f":"arpa*gm/100","x":""},{"key":"life","label":"Customer lifetime","unit":"months","f":"100/churn","x":""},{"key":"ltv","label":"Lifetime value","unit":"money","f":"margin*life","x":""},{"key":"ratio","label":"Lifetime value / CAC","unit":"times","f":"ltv/cac","x":""},{"key":"payback","label":"Months to recover CAC","unit":"months","f":"cac/margin","x":""}],"out":["cac","ltv","ratio","payback"],"checks":[{"label":"Value to cost of 3 or more is a usual aim","f":"ratio>0"}],"notes":["Both customer value and churn are estimates; test them with your own data."]},{"id":"funnel","name":"Sales funnel conversion","fn":"Sales and marketing","sectors":["*"],"kw":["funnel","conversion","leads","pipeline","win","rate","stages","sales","marketing","qualified"],"about":"Shows how many leads are lost at each stage and the overall win rate.","process":["Enter the number reaching each stage.","Conversion = next stage / this stage."],"inputs":[{"key":"stages","label":"Numbers at each stage, first stage first","unit":"series","sample":"5000,1200,420,160,48"},{"key":"value","label":"Value of each won deal","unit":"money","sample":"250000"}],"steps":[{"key":"first","label":"Started","unit":"count","f":"FIRST(stages)","x":""},{"key":"won","label":"Won","unit":"count","f":"LAST(stages)","x":""},{"key":"overall","label":"Overall win rate","unit":"%","f":"won/first*100","x":""},{"key":"revenue","label":"Revenue from won deals","unit":"money","f":"won*value","x":""},{"key":"need","label":"Starting numbers needed per 10 wins","unit":"count","f":"10/(overall/100)","x":""}],"out":["overall","revenue","need"],"checks":[{"label":"Numbers fall or stay equal stage by stage","f":"MAX(stages)=FIRST(stages)"}],"notes":[]},{"id":"roas","name":"Advertising return (ROAS and ROI)","fn":"Sales and marketing","sectors":["Retail and e-commerce","Technology and services","Hospitality and travel","Education and training","Telecom and media"],"kw":["roas","roi","advertising","campaign","return","ad","spend","marketing","cost","per","lead","click"],"about":"Shows what each unit of advertising spend brings back.","process":["ROAS = revenue / ad spend.","ROI also takes out the cost of the goods sold."],"inputs":[{"key":"spend","label":"Ad spend","unit":"money","sample":"200000"},{"key":"revenue","label":"Revenue from the campaign","unit":"money","sample":"900000"},{"key":"gm","label":"Gross margin","unit":"%","sample":"40"},{"key":"leads","label":"Leads","unit":"count","sample":"1500"}],"steps":[{"key":"roas","label":"Return on ad spend","unit":"times","f":"revenue/spend","x":""},{"key":"gp","label":"Gross profit from campaign","unit":"money","f":"revenue*gm/100","x":""},{"key":"roi","label":"Return on investment","unit":"%","f":"(gp-spend)/spend*100","x":""},{"key":"cpl","label":"Cost per lead","unit":"money","f":"spend/leads","x":""}],"out":["roas","roi","cpl"],"checks":[{"label":"Ad spend above zero","f":"spend>0"}],"notes":[]},{"id":"retail-gmroi","name":"Retail productivity: GMROI and sales density","fn":"Sales and marketing","sectors":["Retail and e-commerce","Hospitality and travel"],"kw":["gmroi","retail","inventory","sales","per","square","foot","density","margin","return","stock","turns"],"about":"Shows how well stock and shop space turn into margin.","process":["GMROI = gross margin / average inventory at cost.","Sales density = sales / shop area."],"inputs":[{"key":"sales","label":"Sales","unit":"money","sample":"36000000"},{"key":"cogs","label":"Cost of goods sold","unit":"money","sample":"25200000"},{"key":"inv","label":"Average inventory at cost","unit":"money","sample":"6000000"},{"key":"area","label":"Shop area","unit":"square units","sample":"12000"}],"steps":[{"key":"gm","label":"Gross margin","unit":"money","f":"sales-cogs","x":""},{"key":"gmroi","label":"GMROI","unit":"times","f":"gm/inv","x":""},{"key":"turns","label":"Stock turns","unit":"times","f":"cogs/inv","x":""},{"key":"density","label":"Sales per area","unit":"money","f":"sales/area","x":""}],"out":["gmroi","turns","density"],"checks":[{"label":"GMROI = margin % x turns / (1 - margin %)","f":"ABS(gmroi-(gm/sales)*turns/(1-gm/sales))<0.0001"}],"notes":[]},{"id":"attrition","name":"Staff turnover and cost","fn":"People","sectors":["*"],"kw":["attrition","turnover","staff","leaving","retention","hr","cost","replacement"],"about":"Shows how many people leave and what it costs to replace them.","process":["Turnover rate = leavers / average headcount.","Cost = leavers x replacement cost per person."],"inputs":[{"key":"start","label":"Headcount at start","unit":"people","sample":"520"},{"key":"end","label":"Headcount at end","unit":"people","sample":"540"},{"key":"leavers","label":"Leavers in the period","unit":"people","sample":"78"},{"key":"cost","label":"Cost to replace one person","unit":"money","sample":"120000"}],"steps":[{"key":"avg","label":"Average headcount","unit":"people","f":"(start+end)/2","x":""},{"key":"rate","label":"Turnover rate","unit":"%","f":"leavers/avg*100","x":""},{"key":"total","label":"Cost of replacing leavers","unit":"money","f":"leavers*cost","x":""}],"out":["rate","total"],"checks":[{"label":"Leavers not more than headcount at start","f":"leavers<=start"}],"notes":[]},{"id":"gratuity","name":"Gratuity under the 15/26 formula","fn":"People","sectors":["*"],"kw":["gratuity","retirement","benefit","service","years","last","drawn","salary","payment","of","gratuity","act"],"about":"Works out gratuity as 15 days of last drawn pay for each year of service, using 26 working days a month.","process":["Gratuity = last drawn monthly pay (basic plus dearness) x 15 / 26 x completed years.","Service of more than six months in the last year rounds up to a full year."],"inputs":[{"key":"pay","label":"Last drawn monthly pay","unit":"money","sample":"60000"},{"key":"years","label":"Years of service","unit":"years","sample":"12"},{"key":"months","label":"Extra months in the last year","unit":"months","sample":"7"},{"key":"cap","label":"Statutory ceiling in force (enter the current one)","unit":"money","sample":"2000000"}],"steps":[{"key":"yrs","label":"Years counted","unit":"years","f":"years+IF(months>6,1,0)","x":""},{"key":"gratuity","label":"Gratuity","unit":"money","f":"pay*15/26*yrs","x":""},{"key":"payable","label":"Payable after ceiling","unit":"money","f":"MIN(gratuity,cap)","x":""}],"out":["gratuity","payable"],"checks":[{"label":"Payable not above gratuity","f":"payable<=gratuity"}],"notes":["Check the Act, the latest ceiling and your service rules. This is a calculation aid, not legal advice."]},{"id":"overtime-pay","name":"Overtime pay","fn":"People","sectors":["*"],"kw":["overtime","pay","wages","hours","rate","premium","double","time","shift"],"about":"Adds overtime at the premium rate to normal pay.","process":["Hourly rate = monthly pay / normal hours in the month.","Overtime = overtime hours x hourly rate x premium multiple."],"inputs":[{"key":"monthly","label":"Monthly pay","unit":"money","sample":"40000"},{"key":"normal","label":"Normal hours in the month","unit":"hours","sample":"208"},{"key":"othours","label":"Overtime hours","unit":"hours","sample":"14"},{"key":"mult","label":"Premium multiple","unit":"times","sample":"2"}],"steps":[{"key":"hourly","label":"Hourly rate","unit":"money","f":"monthly/normal","x":""},{"key":"otpay","label":"Overtime pay","unit":"money","f":"othours*hourly*mult","x":""},{"key":"total","label":"Total pay for the month","unit":"money","f":"monthly+otpay","x":""}],"out":["hourly","otpay","total"],"checks":[{"label":"Total at least monthly pay","f":"total>=monthly"}],"notes":[]},{"id":"revenue-per-head","name":"Revenue and profit per employee","fn":"People","sectors":["*"],"kw":["productivity","revenue","per","employee","profit","headcount","staff","cost","ratio"],"about":"Compares output and pay with the number of people.","process":["Divide revenue and profit by headcount.","Staff cost as a share of revenue shows how people-heavy the business is."],"inputs":[{"key":"revenue","label":"Revenue","unit":"money","sample":"120000000"},{"key":"profit","label":"Net profit","unit":"money","sample":"9000000"},{"key":"staffcost","label":"Total staff cost","unit":"money","sample":"36000000"},{"key":"heads","label":"Average headcount","unit":"people","sample":"540"}],"steps":[{"key":"rph","label":"Revenue per employee","unit":"money","f":"revenue/heads","x":""},{"key":"pph","label":"Profit per employee","unit":"money","f":"profit/heads","x":""},{"key":"cph","label":"Staff cost per employee","unit":"money","f":"staffcost/heads","x":""},{"key":"share","label":"Staff cost as share of revenue","unit":"%","f":"staffcost/revenue*100","x":""}],"out":["rph","pph","cph","share"],"checks":[{"label":"Staff cost not above revenue","f":"staffcost<=revenue"}],"notes":[]},{"id":"evm","name":"Project progress: earned value","fn":"Project","sectors":["Construction and real estate","Manufacturing","Technology and services","Energy and utilities","Public sector and social enterprise","Telecom and media"],"kw":["earned","value","evm","cost","performance","schedule","performance","cpi","spi","estimate","at","completion","project","control","progress"],"about":"Compares work done, work planned and money spent to forecast the finish.","process":["Earned value = percent complete x budget at completion.","CPI = earned / actual cost. SPI = earned / planned value.","Forecast at completion = budget / CPI."],"inputs":[{"key":"bac","label":"Total budget","unit":"money","sample":"10000000"},{"key":"planned","label":"Planned percent complete by now","unit":"%","sample":"50"},{"key":"done","label":"Actual percent complete","unit":"%","sample":"45"},{"key":"ac","label":"Actual cost so far","unit":"money","sample":"5200000"}],"steps":[{"key":"pv","label":"Planned value","unit":"money","f":"bac*planned/100","x":""},{"key":"ev","label":"Earned value","unit":"money","f":"bac*done/100","x":""},{"key":"cpi","label":"Cost performance index","unit":"ratio","f":"ev/ac","x":""},{"key":"spi","label":"Schedule performance index","unit":"ratio","f":"ev/pv","x":""},{"key":"eac","label":"Forecast cost at completion","unit":"money","f":"bac/cpi","x":""},{"key":"vac","label":"Forecast over (-) or under (+) budget","unit":"money","f":"bac-eac","x":""}],"out":["cpi","spi","eac","vac"],"checks":[{"label":"Percent values between 0 and 100","f":"AND(planned>=0,planned<=100,done>=0,done<=100)"}],"notes":["Below 1 on either index means behind plan or over cost."]},{"id":"pert","name":"Three-point time or cost estimate (PERT)","fn":"Project","sectors":["*"],"kw":["pert","three","point","estimate","optimistic","pessimistic","duration","risk","uncertainty"],"about":"Combines best, likely and worst estimates into one expected value with a spread.","process":["Expected = (best + 4 x likely + worst) / 6.","Spread = (worst - best) / 6."],"inputs":[{"key":"a","label":"Best case","unit":"number","sample":"20"},{"key":"m","label":"Most likely","unit":"number","sample":"30"},{"key":"b","label":"Worst case","unit":"number","sample":"55"}],"steps":[{"key":"e","label":"Expected","unit":"number","f":"(a+4*m+b)/6","x":""},{"key":"sd","label":"Spread (standard deviation)","unit":"number","f":"(b-a)/6","x":""},{"key":"p95","label":"About 95 percent sure of finishing by","unit":"number","f":"e+NORMSINV(0.95)*sd","x":""}],"out":["e","sd","p95"],"checks":[{"label":"Cases in order","f":"AND(a<=m,m<=b)"}],"notes":[]},{"id":"project-roi","name":"Return on a project or initiative","fn":"Project","sectors":["*"],"kw":["roi","return","on","investment","payback","benefit","cost","initiative","business","case"],"about":"Compares total benefits over a period with what the project costs.","process":["Net benefit = benefits less cost. ROI = net benefit / cost.","Payback = cost / benefit per year."],"inputs":[{"key":"cost","label":"Total cost","unit":"money","sample":"2500000"},{"key":"benefit","label":"Benefit per year","unit":"money","sample":"900000"},{"key":"years","label":"Years of benefit","unit":"years","sample":"5"}],"steps":[{"key":"total","label":"Total benefits","unit":"money","f":"benefit*years","x":""},{"key":"net","label":"Net benefit","unit":"money","f":"total-cost","x":""},{"key":"roi","label":"Return on investment","unit":"%","f":"net/cost*100","x":""},{"key":"payback","label":"Payback","unit":"years","f":"cost/benefit","x":""}],"out":["net","roi","payback"],"checks":[{"label":"Payback inside benefit period if net benefit is positive","f":"IF(net>0,payback<years,1)=1"}],"notes":[]},{"id":"hotel-kpi","name":"Hotel occupancy, average rate and RevPAR","fn":"Sales and marketing","sectors":["Hospitality and travel"],"kw":["hotel","occupancy","adr","revpar","rooms","revenue","hospitality","revenue","per","available","room"],"about":"Measures how full a hotel is, what it earns per occupied room and per available room.","process":["Occupancy = rooms sold / rooms available.","ADR = room revenue / rooms sold. RevPAR = room revenue / rooms available (also occupancy x ADR)."],"inputs":[{"key":"rooms","label":"Rooms in the hotel","unit":"count","sample":"80"},{"key":"days","label":"Days in the period","unit":"days","sample":"30"},{"key":"sold","label":"Room nights sold","unit":"count","sample":"1560"},{"key":"revenue","label":"Room revenue","unit":"money","sample":"7020000"}],"steps":[{"key":"avail","label":"Room nights available","unit":"count","f":"rooms*days","x":""},{"key":"occ","label":"Occupancy","unit":"%","f":"sold/avail*100","x":""},{"key":"adr","label":"Average daily rate","unit":"money","f":"revenue/sold","x":""},{"key":"revpar","label":"RevPAR","unit":"money","f":"revenue/avail","x":""}],"out":["occ","adr","revpar"],"checks":[{"label":"RevPAR equals occupancy times ADR","f":"ABS(revpar-occ/100*adr)<0.0001"}],"notes":[]},{"id":"hospital-kpi","name":"Hospital beds: occupancy and stay","fn":"Operations","sectors":["Healthcare"],"kw":["hospital","bed","occupancy","average","length","of","stay","alos","turnover","patients","days"],"about":"Shows how fully beds are used and how long patients stay.","process":["Occupancy = patient days / bed days available.","Average stay = patient days / discharges. Turnover = discharges per bed."],"inputs":[{"key":"beds","label":"Beds","unit":"count","sample":"250"},{"key":"days","label":"Days in the period","unit":"days","sample":"30"},{"key":"pdays","label":"Patient days","unit":"count","sample":"5900"},{"key":"discharges","label":"Discharges","unit":"count","sample":"1180"}],"steps":[{"key":"bd","label":"Bed days available","unit":"count","f":"beds*days","x":""},{"key":"occ","label":"Bed occupancy","unit":"%","f":"pdays/bd*100","x":""},{"key":"alos","label":"Average length of stay","unit":"days","f":"pdays/discharges","x":""},{"key":"tr","label":"Discharges per bed","unit":"count","f":"discharges/beds","x":""}],"out":["occ","alos","tr"],"checks":[{"label":"Patient days not above bed days","f":"pdays<=bd"}],"notes":[]},{"id":"crop-margin","name":"Crop gross margin","fn":"Costing","sectors":["Agriculture and food"],"kw":["crop","farm","gross","margin","yield","price","cost","per","acre","hectare","agriculture","profit"],"about":"Works out the margin per unit of land from yield, price and costs.","process":["Revenue = yield x price. Gross margin = revenue less variable costs.","Break-even yield shows the lowest yield that still covers cost."],"inputs":[{"key":"area","label":"Area","unit":"acres","sample":"20"},{"key":"yld","label":"Yield","unit":"quintal per acre","sample":"18"},{"key":"price","label":"Selling price","unit":"money per quintal","sample":"2300"},{"key":"vc","label":"Variable cost per acre","unit":"money","sample":"24000"},{"key":"fixed","label":"Fixed cost for the whole area","unit":"money","sample":"60000"}],"steps":[{"key":"rev","label":"Revenue per acre","unit":"money","f":"yld*price","x":""},{"key":"gm","label":"Gross margin per acre","unit":"money","f":"rev-vc","x":""},{"key":"total","label":"Profit for the whole area","unit":"money","f":"gm*area-fixed","x":""},{"key":"bey","label":"Break-even yield","unit":"quintal per acre","f":"(vc+fixed/area)/price","x":""}],"out":["gm","total","bey"],"checks":[{"label":"Break-even yield reproduces zero profit","f":"ABS(bey*price*area-(vc*area+fixed))<0.01"}],"notes":[]},{"id":"rental-yield","name":"Property rental yield","fn":"Finance","sectors":["Construction and real estate"],"kw":["rental","yield","property","real","estate","rent","price","net","income","gross","cap","rate"],"about":"Compares yearly rent with the property price.","process":["Gross yield = yearly rent / price.","Net yield removes running costs and vacancy."],"inputs":[{"key":"price","label":"Property price","unit":"money","sample":"12000000"},{"key":"rent","label":"Monthly rent","unit":"money","sample":"55000"},{"key":"vacancy","label":"Months empty in a year","unit":"months","sample":"1"},{"key":"costs","label":"Yearly running costs","unit":"money","sample":"90000"}],"steps":[{"key":"gross","label":"Gross yield","unit":"%","f":"rent*12/price*100","x":""},{"key":"income","label":"Rent actually received","unit":"money","f":"rent*(12-vacancy)","x":""},{"key":"net","label":"Net yield","unit":"%","f":"(income-costs)/price*100","x":""}],"out":["gross","net"],"checks":[{"label":"Net yield not above gross yield","f":"net<=gross"}],"notes":[]},{"id":"bank-quality","name":"Loan book quality and provisions","fn":"Risk review","sectors":["Banking and insurance"],"kw":["npa","gross","non","performing","assets","provision","coverage","credit","loan","book","bank","asset","quality"],"about":"Measures how much of a loan book is in trouble and how well provisions cover it.","process":["Gross NPA ratio = bad loans / total loans.","Net NPA removes provisions held. Coverage = provisions / bad loans."],"inputs":[{"key":"loans","label":"Total loans","unit":"money","sample":"80000000"},{"key":"npa","label":"Loans classed as non-performing","unit":"money","sample":"2400000"},{"key":"prov","label":"Provisions held against them","unit":"money","sample":"1500000"}],"steps":[{"key":"gnpa","label":"Gross NPA ratio","unit":"%","f":"npa/loans*100","x":""},{"key":"nnpa","label":"Net NPA ratio","unit":"%","f":"(npa-prov)/(loans-prov)*100","x":""},{"key":"cov","label":"Provision coverage","unit":"%","f":"prov/npa*100","x":""}],"out":["gnpa","nnpa","cov"],"checks":[{"label":"Net NPA not above gross","f":"nnpa<=gnpa"},{"label":"Provisions not above bad loans","f":"prov<=npa"}],"notes":[]},{"id":"insurance-ratio","name":"Insurer combined ratio","fn":"Accounting","sectors":["Banking and insurance"],"kw":["insurance","combined","ratio","loss","ratio","expense","ratio","underwriting","premium","claims"],"about":"Shows whether an insurer's premiums cover claims and costs.","process":["Loss ratio = claims / premium. Expense ratio = expenses / premium.","Combined ratio below 100 percent means an underwriting profit."],"inputs":[{"key":"premium","label":"Premium earned","unit":"money","sample":"50000000"},{"key":"claims","label":"Claims incurred","unit":"money","sample":"33000000"},{"key":"expenses","label":"Expenses","unit":"money","sample":"13500000"}],"steps":[{"key":"lr","label":"Loss ratio","unit":"%","f":"claims/premium*100","x":""},{"key":"er","label":"Expense ratio","unit":"%","f":"expenses/premium*100","x":""},{"key":"cr","label":"Combined ratio","unit":"%","f":"lr+er","x":""},{"key":"uw","label":"Underwriting result","unit":"money","f":"premium-claims-expenses","x":""}],"out":["lr","er","cr","uw"],"checks":[{"label":"Underwriting result consistent with the ratio","f":"ABS(uw-premium*(100-cr)/100)<0.01"}],"notes":[]},{"id":"freight-cost","name":"Freight cost per tonne-km","fn":"Costing","sectors":["Logistics and supply chain","Manufacturing","Agriculture and food","Mining and metals","Retail and e-commerce"],"kw":["freight","transport","cost","per","tonne","km","truck","fuel","driver","toll","load","logistics","route"],"about":"Builds the cost of a truck trip and the cost to move a tonne one kilometre.","process":["Add fuel, driver, tolls and truck cost for the trip.","Divide by tonnes carried and distance."],"inputs":[{"key":"km","label":"Trip distance","unit":"km","sample":"600"},{"key":"mileage","label":"Fuel use","unit":"km per litre","sample":"3.5"},{"key":"fuel","label":"Fuel price","unit":"money per litre","sample":"90"},{"key":"driver","label":"Driver and crew cost for the trip","unit":"money","sample":"4500"},{"key":"toll","label":"Tolls and fees","unit":"money","sample":"3200"},{"key":"truck","label":"Truck cost per day (finance, tax, repair)","unit":"money","sample":"3000"},{"key":"days","label":"Days for the trip","unit":"days","sample":"2"},{"key":"tonnes","label":"Load carried","unit":"tonnes","sample":"18"}],"steps":[{"key":"fuelcost","label":"Fuel cost","unit":"money","f":"km/mileage*fuel","x":""},{"key":"trip","label":"Cost of the trip","unit":"money","f":"fuelcost+driver+toll+truck*days","x":""},{"key":"tkm","label":"Tonne-km moved","unit":"tonne-km","f":"tonnes*km","x":""},{"key":"per","label":"Cost per tonne-km","unit":"money","f":"trip/tkm","x":""},{"key":"pert","label":"Cost per tonne","unit":"money","f":"trip/tonnes","x":""}],"out":["trip","per","pert"],"checks":[{"label":"Cost per tonne-km times tonne-km gives trip cost","f":"ABS(per*tkm-trip)<0.001"}],"notes":[]},{"id":"ore-value","name":"Value of a tonne of ore","fn":"Costing","sectors":["Mining and metals"],"kw":["ore","grade","recovery","metal","price","smelter","mining","value","per","tonne","cut","off","cost"],"about":"Shows what a tonne of ore is worth after recovery and cost.","process":["Metal in a tonne = grade x recovery.","Value = metal x net price. Compare with cost per tonne for the margin."],"inputs":[{"key":"grade","label":"Grade","unit":"%","sample":"1.8"},{"key":"rec","label":"Recovery","unit":"%","sample":"88"},{"key":"price","label":"Metal price","unit":"money per tonne of metal","sample":"700000"},{"key":"deduct","label":"Deductions (refining and transport)","unit":"%","sample":"12"},{"key":"cost","label":"Mining and processing cost per tonne of ore","unit":"money","sample":"9000"}],"steps":[{"key":"metal","label":"Metal per tonne of ore","unit":"tonne","f":"grade/100*rec/100","x":""},{"key":"gross","label":"Value per tonne of ore","unit":"money","f":"metal*price","x":""},{"key":"net","label":"Value after deductions","unit":"money","f":"gross*(1-deduct/100)","x":""},{"key":"margin","label":"Margin per tonne of ore","unit":"money","f":"net-cost","x":""},{"key":"cutoff","label":"Lowest grade that pays its cost","unit":"%","f":"cost/((rec/100)*price*(1-deduct/100))*100","x":""}],"out":["net","margin","cutoff"],"checks":[{"label":"At cut-off grade the margin is zero","f":"ABS((cutoff/100*rec/100*price*(1-deduct/100))-cost)<0.0001"}],"notes":[]},{"id":"cost-per-student","name":"Cost per student and class sizes","fn":"Costing","sectors":["Education and training"],"kw":["school","college","cost","per","student","teacher","ratio","fees","class","size","education","budget"],"about":"Shows what each learner costs and how many learners each teacher supports.","process":["Cost per student = total cost / students.","Student-teacher ratio = students / teachers."],"inputs":[{"key":"students","label":"Students","unit":"count","sample":"1200"},{"key":"teachers","label":"Teachers","unit":"count","sample":"48"},{"key":"cost","label":"Total yearly cost","unit":"money","sample":"54000000"},{"key":"fees","label":"Average fee per student","unit":"money","sample":"52000"}],"steps":[{"key":"cps","label":"Cost per student","unit":"money","f":"cost/students","x":""},{"key":"str","label":"Students per teacher","unit":"ratio","f":"students/teachers","x":""},{"key":"gap","label":"Fee income less cost per student","unit":"money","f":"fees-cps","x":""},{"key":"cover","label":"Fee income as share of cost","unit":"%","f":"fees*students/cost*100","x":""}],"out":["cps","str","gap","cover"],"checks":[{"label":"Teachers fewer than students","f":"teachers<students"}],"notes":[]},{"id":"telecom-arpu","name":"Telecom revenue per user and churn","fn":"Sales and marketing","sectors":["Telecom and media","Technology and services"],"kw":["arpu","churn","subscribers","telecom","revenue","per","user","subscribers","average","lifetime"],"about":"Tracks revenue per subscriber, churn and the average subscriber lifetime.","process":["ARPU = revenue / average subscribers.","Churn = leavers / opening subscribers. Lifetime = 1 / churn."],"inputs":[{"key":"revenue","label":"Revenue for the month","unit":"money","sample":"90000000"},{"key":"open","label":"Subscribers at start","unit":"count","sample":"400000"},{"key":"close","label":"Subscribers at end","unit":"count","sample":"410000"},{"key":"leavers","label":"Subscribers who left","unit":"count","sample":"9000"}],"steps":[{"key":"avg","label":"Average subscribers","unit":"count","f":"(open+close)/2","x":""},{"key":"arpu","label":"ARPU","unit":"money","f":"revenue/avg","x":""},{"key":"churn","label":"Monthly churn","unit":"%","f":"leavers/open*100","x":""},{"key":"life","label":"Average lifetime","unit":"months","f":"100/churn","x":""}],"out":["arpu","churn","life"],"checks":[{"label":"Leavers not more than opening subscribers","f":"leavers<=open"}],"notes":[]},{"id":"yield-scrap","name":"Production yield and scrap cost","fn":"Operations","sectors":["Manufacturing","Electronics and semiconductor","Agriculture and food"],"kw":["yield","scrap","rework","first","pass","good","units","cost","of","poor","quality","waste"],"about":"Shows how much material and money is lost to scrap and rework.","process":["First-pass yield = good first time / started.","Cost of poor quality = scrap x material and work cost + rework x rework cost."],"inputs":[{"key":"started","label":"Units started","unit":"units","sample":"10000"},{"key":"good","label":"Good first time","unit":"units","sample":"9180"},{"key":"rework","label":"Reworked and passed","unit":"units","sample":"500"},{"key":"scrap","label":"Scrapped","unit":"units","sample":"320"},{"key":"cost","label":"Cost of a unit up to the point it is scrapped","unit":"money","sample":"260"},{"key":"rwcost","label":"Rework cost per unit","unit":"money","sample":"40"}],"steps":[{"key":"fpy","label":"First-pass yield","unit":"%","f":"good/started*100","x":""},{"key":"final","label":"Final yield","unit":"%","f":"(good+rework)/started*100","x":""},{"key":"copq","label":"Cost of poor quality","unit":"money","f":"scrap*cost+rework*rwcost","x":""},{"key":"per","label":"Cost of poor quality per unit started","unit":"money","f":"copq/started","x":""}],"out":["fpy","final","copq","per"],"checks":[{"label":"Units account for those started","f":"good+rework+scrap=started"}],"notes":[]},{"id":"mortgage-afford","name":"How much home loan can I afford","fn":"Finance","sectors":["Construction and real estate","Banking and insurance"],"kw":["mortgage","home","loan","afford","income","emi","ratio","borrow","eligibility","house"],"about":"Finds the loan a household can carry if repayments take an agreed share of income.","process":["Allowed repayment = income x share you are willing to pay.","The loan is the present value of those repayments over the term."],"inputs":[{"key":"income","label":"Monthly household income","unit":"money","sample":"150000"},{"key":"other","label":"Other monthly loan repayments","unit":"money","sample":"15000"},{"key":"share","label":"Share of income for loans","unit":"%","sample":"40"},{"key":"rate","label":"Yearly interest rate","unit":"%","sample":"9"},{"key":"years","label":"Loan period","unit":"years","sample":"20"}],"steps":[{"key":"room","label":"Repayment you can afford","unit":"money","f":"income*share/100-other","x":""},{"key":"loan","label":"Loan you can carry","unit":"money","f":"PV(rate/100/12,years*12,room)","x":""},{"key":"paid","label":"Total you would repay","unit":"money","f":"room*years*12","x":""}],"out":["room","loan","paid"],"checks":[{"label":"Repayment room above zero","f":"room>0"}],"notes":[]},{"id":"epc-cost-buildup","name":"Project cost build-up with contingency and escalation","fn":"Costing","sectors":["Energy and utilities","Construction and real estate","Manufacturing"],"kw":["epc","project","cost","estimate","contingency","escalation","indirect","engineering","procurement","construction","budget","capex","build","up"],"about":"Builds the full project cost from direct cost, indirect cost, contingency and price escalation.","process":["Add indirect costs as a share of direct cost.","Add contingency for what is not yet known.","Escalate for the time until the money is spent."],"inputs":[{"key":"direct","label":"Direct cost (equipment, materials, labour)","unit":"money","sample":"80000000"},{"key":"indirect","label":"Indirect costs (site, supervision, temporary works)","unit":"%","sample":"12"},{"key":"engineering","label":"Engineering and project management","unit":"%","sample":"6"},{"key":"contingency","label":"Contingency","unit":"%","sample":"8"},{"key":"esc","label":"Yearly price escalation","unit":"%","sample":"4"},{"key":"years","label":"Average years until spend","unit":"years","sample":"1.5"}],"steps":[{"key":"ind","label":"Indirect costs","unit":"money","f":"direct*indirect/100","x":""},{"key":"eng","label":"Engineering and project management","unit":"money","f":"(direct+ind)*engineering/100","x":""},{"key":"subtotal","label":"Cost before contingency","unit":"money","f":"direct+ind+eng","x":""},{"key":"cont","label":"Contingency amount","unit":"money","f":"subtotal*contingency/100","x":""},{"key":"base","label":"Cost at today's prices","unit":"money","f":"subtotal+cont","x":""},{"key":"total","label":"Cost after escalation","unit":"money","f":"base*POW(1+esc/100,years)","x":""},{"key":"uplift","label":"Total above direct cost","unit":"%","f":"(total/direct-1)*100","x":""}],"out":["base","total","uplift"],"checks":[{"label":"Total not below direct cost","f":"total>=direct"},{"label":"Percentages are not negative","f":"MIN(indirect,engineering,contingency,esc)>=0"}],"notes":[]},{"id":"epc-contract-margin","name":"Contract price and margin for a turnkey job","fn":"Costing","sectors":["Energy and utilities","Construction and real estate","Manufacturing"],"kw":["contract","price","margin","turnkey","epc","bid","tender","risk","provision","warranty","overhead","markup","quote"],"about":"Sets the price for a contract that covers the cost, risk, warranty and overheads and still leaves the margin you aim for.","process":["Add provisions for risk and warranty to the cost.","Add the share of group overhead the job should carry.","Divide by (1 - target margin) to get the price."],"inputs":[{"key":"cost","label":"Estimated cost of the job","unit":"money","sample":"95000000"},{"key":"risk","label":"Risk provision","unit":"%","sample":"3"},{"key":"warranty","label":"Warranty provision","unit":"%","sample":"1.5"},{"key":"overhead","label":"Overhead share","unit":"%","sample":"4"},{"key":"margin","label":"Target margin on price","unit":"%","sample":"12"}],"steps":[{"key":"prov","label":"Provisions","unit":"money","f":"cost*(risk+warranty)/100","x":""},{"key":"oh","label":"Overhead carried","unit":"money","f":"cost*overhead/100","x":""},{"key":"full","label":"Full cost","unit":"money","f":"cost+prov+oh","x":""},{"key":"price","label":"Contract price","unit":"money","f":"full/(1-margin/100)","x":""},{"key":"profit","label":"Profit if provisions are not used","unit":"money","f":"price-cost-oh","x":""},{"key":"check_m","label":"Margin on price after provisions","unit":"%","f":"(price-full)/price*100","x":""}],"out":["full","price","check_m"],"checks":[{"label":"Margin on price equals the target","f":"ABS(check_m-margin)<0.0001"},{"label":"Margin below 100","f":"margin<100"}],"notes":["If provisions are not needed they return to profit. Review them at every stage."]},{"id":"progress-payment","name":"Progress payments, advance and retention","fn":"Cash flow","sectors":["Energy and utilities","Construction and real estate","Manufacturing","Public sector and social enterprise"],"kw":["progress","payment","advance","retention","milestone","certified","contractor","cash","flow","invoice","percent","complete","epc"],"about":"Shows the cash a contractor receives as work is certified, after the advance is recovered and retention is held.","process":["Certified value = contract value x cumulative percent complete.","Recover the advance in proportion to progress; hold back the retention share.","Cash in so far = advance + certified - recovery - retention."],"inputs":[{"key":"value","label":"Contract value","unit":"money","sample":"100000000"},{"key":"advance","label":"Advance received at start","unit":"%","sample":"10"},{"key":"ret","label":"Retention held back","unit":"%","sample":"5"},{"key":"cum","label":"Cumulative percent complete at each certificate","unit":"series","sample":"15,35,60,85,100"}],"steps":[{"key":"adv","label":"Advance amount","unit":"money","f":"value*advance/100","x":""},{"key":"gross","label":"Certified value to date","unit":"series","f":"value*cum/100","x":""},{"key":"recovery","label":"Advance recovered to date","unit":"series","f":"adv*cum/100","x":""},{"key":"retained","label":"Retention held to date","unit":"series","f":"gross*ret/100","x":""},{"key":"cashin","label":"Cash received to date","unit":"series","f":"adv+gross-recovery-retained","x":""},{"key":"final","label":"Cash received at 100 percent","unit":"money","f":"LAST(cashin)","x":""},{"key":"held","label":"Retention still to be released","unit":"money","f":"LAST(retained)","x":""}],"out":["final","held"],"checks":[{"label":"At full completion cash equals value less retention","f":"ABS(final-(value-held))<0.01"},{"label":"Progress rises","f":"LAST(cum)>=FIRST(cum)"}],"notes":["Terms differ by contract. Use the percentages in yours."]},{"id":"solar-project-return","name":"Solar project return over its life","fn":"Finance","sectors":["Energy and utilities","Agriculture and food","Manufacturing","Construction and real estate","Healthcare","Education and training"],"kw":["solar","project","irr","npv","payback","ppa","tariff","degradation","capex","energy","sales","renewable","return"],"about":"Gives the return on a solar plant from its cost, yearly energy, tariff, running cost and yearly loss of output.","process":["Energy in each year falls by the yearly loss.","Income is energy times tariff, less running cost.","Put the build cost at year 0 and find NPV, IRR and payback."],"inputs":[{"key":"capex","label":"Build cost","unit":"money","sample":"50000000"},{"key":"kwp","label":"Plant size","unit":"kWp","sample":"1000"},{"key":"yieldkwh","label":"Energy per kWp in year 1","unit":"kWh","sample":"1550"},{"key":"tariff","label":"Tariff","unit":"money per kWh","sample":"4.5"},{"key":"om","label":"Running cost per year","unit":"money","sample":"600000"},{"key":"degr","label":"Yearly loss of output","unit":"%","sample":"0.6"},{"key":"life","label":"Life","unit":"years","sample":"25"},{"key":"rate","label":"Discount rate","unit":"%","sample":"10"}],"steps":[{"key":"yrs","label":"Years","unit":"series","f":"SEQ(life)","x":""},{"key":"energy","label":"Energy each year","unit":"series","f":"kwp*yieldkwh*POW(1-degr/100,yrs-1)","x":""},{"key":"net","label":"Net income each year","unit":"series","f":"energy*tariff-om","x":""},{"key":"cf","label":"Cash flows with build cost","unit":"series","f":"JOIN(0-capex,net)","x":""},{"key":"npv","label":"Net present value","unit":"money","f":"NPV0(rate/100,cf)","x":""},{"key":"irr","label":"IRR","unit":"%","f":"IRR(cf)*100","x":""},{"key":"payback","label":"Payback","unit":"years","f":"PAYBACK(cf)","x":""}],"out":["npv","irr","payback"],"checks":[{"label":"Cash flow has one more item than years","f":"LEN(cf)=life+1"},{"label":"NPV at the IRR is close to zero","f":"ABS(NPV0(irr/100,cf))<1"}],"notes":["Add tax, inverter replacement and grid costs for a full model."]},{"id":"debt-cover-years","name":"Debt cover year by year","fn":"Finance","sectors":["Energy and utilities","Construction and real estate","Banking and insurance","Public sector and social enterprise"],"kw":["dscr","debt","service","cover","annual","cfads","project","finance","loan","tenor","lender","minimum","average"],"about":"Tests every year of a project loan: cash available for debt service against the level instalment.","process":["Work out the level yearly instalment for the loan.","Divide each year's cash available by it.","Lenders look at the lowest and the average year."],"inputs":[{"key":"debt","label":"Loan","unit":"money","sample":"300000000"},{"key":"rate","label":"Interest rate","unit":"%","sample":"9.5"},{"key":"tenor","label":"Repayment years","unit":"years","sample":"12"},{"key":"cfads","label":"Cash available for debt service, year 1 first","unit":"series","sample":"42000000,44000000,46000000,47000000,48000000,49000000,50000000,50000000,51000000,51000000,52000000,52000000"},{"key":"minimum","label":"Lender minimum cover","unit":"times","sample":"1.2"}],"steps":[{"key":"ds","label":"Yearly instalment","unit":"money","f":"PMT(rate/100,tenor,debt)","x":""},{"key":"dscr","label":"Cover each year","unit":"series","f":"cfads/ds","x":""},{"key":"low","label":"Lowest cover","unit":"times","f":"MIN(dscr)","x":""},{"key":"avg","label":"Average cover","unit":"times","f":"AVG(dscr)","x":""},{"key":"ok","label":"Meets lender minimum every year (1 yes, 0 no)","unit":"flag","f":"IF(low>=minimum,1,0)","x":""},{"key":"maxdebt","label":"Largest loan the lowest year can carry","unit":"money","f":"PV(rate/100,tenor,MIN(cfads)/minimum)","x":""}],"out":["ds","low","avg","ok","maxdebt"],"checks":[{"label":"Series covers the repayment years","f":"LEN(cfads)=tenor"},{"label":"Loan repaid by the instalments","f":"ABS(PV(rate/100,tenor,ds)-debt)<0.01*debt/1000"}],"notes":[]},{"id":"cable-loss-cost","name":"Cable and conductor loss cost","fn":"Engineering","sectors":["Energy and utilities","Manufacturing","Construction and real estate","Electronics and semiconductor","Telecom and media"],"kw":["cable","loss","i","squared","r","resistance","energy","loss","cost","conductor","size","three","phase","feeder","yearly"],"about":"Finds the energy lost as heat in a cable over a year and what it costs.","process":["Loss in a three-phase circuit = 3 x current squared x resistance of one conductor.","Multiply by hours at that load and by the price of energy."],"inputs":[{"key":"amps","label":"Load current","unit":"amps","sample":"150"},{"key":"r","label":"Conductor resistance per km","unit":"ohm per km","sample":"0.32"},{"key":"km","label":"Length","unit":"km","sample":"0.4"},{"key":"hours","label":"Hours per year at this load","unit":"hours","sample":"4500"},{"key":"tariff","label":"Energy price","unit":"money per kWh","sample":"8"}],"steps":[{"key":"rohm","label":"Resistance of one conductor","unit":"ohm","f":"r*km","x":""},{"key":"kw","label":"Loss while carrying the load","unit":"kW","f":"3*amps^2*rohm/1000","x":""},{"key":"kwh","label":"Energy lost in a year","unit":"kWh","f":"kw*hours","x":""},{"key":"cost","label":"Cost of the loss each year","unit":"money","f":"kwh*tariff","x":""}],"out":["kw","kwh","cost"],"checks":[{"label":"Loss is not negative","f":"kw>=0"}],"notes":["Resistance rises with temperature. Use the value at working temperature for a closer answer."]},{"id":"transformer-tco","name":"Transformer cost of ownership with losses","fn":"Engineering","sectors":["Energy and utilities","Manufacturing","Construction and real estate","Electronics and semiconductor"],"kw":["transformer","total","cost","ownership","losses","no","load","load","loss","evaluation","purchase","efficiency","life","kva"],"about":"Adds the value of a transformer's losses over its life to its purchase price, so cheaper-to-run units can win.","process":["Fixed (no-load) loss runs every hour; load loss varies with the square of loading.","Value the yearly loss energy and discount it over the life."],"inputs":[{"key":"price","label":"Purchase price","unit":"money","sample":"1800000"},{"key":"noload","label":"No-load loss","unit":"kW","sample":"1.2"},{"key":"loadloss","label":"Load loss at full load","unit":"kW","sample":"9.5"},{"key":"loading","label":"Average loading","unit":"%","sample":"55"},{"key":"hours","label":"Hours on supply per year","unit":"hours","sample":"8760"},{"key":"tariff","label":"Energy price","unit":"money per kWh","sample":"8"},{"key":"life","label":"Life","unit":"years","sample":"25"},{"key":"rate","label":"Discount rate","unit":"%","sample":"10"}],"steps":[{"key":"lossavg","label":"Average loss","unit":"kW","f":"noload+loadloss*(loading/100)^2","x":""},{"key":"kwh","label":"Loss energy per year","unit":"kWh","f":"lossavg*hours","x":""},{"key":"cost","label":"Loss cost per year","unit":"money","f":"kwh*tariff","x":""},{"key":"pvloss","label":"Present value of losses","unit":"money","f":"PV(rate/100,life,cost)","x":""},{"key":"tco","label":"Total cost of ownership","unit":"money","f":"price+pvloss","x":""}],"out":["kwh","pvloss","tco"],"checks":[{"label":"Losses add to a positive cost","f":"pvloss>0"}],"notes":[]},{"id":"motor-replace","name":"Motor replacement payback","fn":"Finance","sectors":["Manufacturing","Energy and utilities","Mining and metals","Agriculture and food","Construction and real estate"],"kw":["motor","replacement","efficiency","energy","saving","payback","high","efficiency","retrofit","electricity","hours","kw"],"about":"Shows the saving and payback from replacing an old motor with a more efficient one.","process":["Electrical input = shaft power / efficiency.","Saving = difference in input x hours x energy price."],"inputs":[{"key":"kw","label":"Shaft power","unit":"kW","sample":"55"},{"key":"eold","label":"Efficiency of old motor","unit":"%","sample":"88"},{"key":"enew","label":"Efficiency of new motor","unit":"%","sample":"94.5"},{"key":"hours","label":"Running hours per year","unit":"hours","sample":"6000"},{"key":"tariff","label":"Energy price","unit":"money per kWh","sample":"8"},{"key":"cost","label":"Cost of new motor and fitting","unit":"money","sample":"250000"}],"steps":[{"key":"inold","label":"Input power, old","unit":"kW","f":"kw/(eold/100)","x":""},{"key":"innew","label":"Input power, new","unit":"kW","f":"kw/(enew/100)","x":""},{"key":"kwhsave","label":"Energy saved per year","unit":"kWh","f":"(inold-innew)*hours","x":""},{"key":"save","label":"Money saved per year","unit":"money","f":"kwhsave*tariff","x":""},{"key":"payback","label":"Payback","unit":"years","f":"cost/save","x":""}],"out":["kwhsave","save","payback"],"checks":[{"label":"New motor is the more efficient","f":"enew>eold"}],"notes":[]},{"id":"battery-lcos","name":"Cost of each unit of energy a battery stores and delivers","fn":"Finance","sectors":["Energy and utilities","Telecom and media","Healthcare","Technology and services"],"kw":["battery","storage","cost","per","kwh","throughput","cycles","lcos","life","cycle","degradation","efficiency","bess"],"about":"Spreads the battery cost over all the energy it will deliver in its life.","process":["Energy delivered per cycle = size x usable share x efficiency.","Total delivered = per cycle x cycles in life.","Cost per kWh = (build cost + running cost over the life) / total delivered."],"inputs":[{"key":"capex","label":"Battery system cost","unit":"money","sample":"20000000"},{"key":"kwh","label":"Battery size","unit":"kWh","sample":"2000"},{"key":"dod","label":"Usable share","unit":"%","sample":"90"},{"key":"eff","label":"Round-trip efficiency","unit":"%","sample":"88"},{"key":"cycles","label":"Cycles in life","unit":"count","sample":"6000"},{"key":"om","label":"Running cost over the life","unit":"money","sample":"1500000"}],"steps":[{"key":"per","label":"Energy delivered per cycle","unit":"kWh","f":"kwh*dod/100*eff/100","x":""},{"key":"total","label":"Energy delivered in life","unit":"kWh","f":"per*cycles","x":""},{"key":"lcos","label":"Cost per kWh delivered","unit":"money","f":"(capex+om)/total","x":""}],"out":["total","lcos"],"checks":[{"label":"Delivered energy is below size times cycles","f":"total<=kwh*cycles"}],"notes":[]},{"id":"pv-string","name":"Solar string length","fn":"Engineering","sectors":["Energy and utilities","Agriculture and food","Manufacturing","Construction and real estate"],"kw":["pv","string","modules","series","voltage","inverter","window","cold","temperature","open","circuit","mppt","sizing"],"about":"Finds how many panels can go in one string so the voltage stays inside the inverter's range, cold and hot.","process":["On the coldest day the open-circuit voltage rises; it must stay below the inverter's maximum.","On the hottest day the working voltage falls; it must stay above the inverter's minimum."],"inputs":[{"key":"voc","label":"Panel open-circuit voltage","unit":"volts","sample":"49.5"},{"key":"vmp","label":"Panel working voltage","unit":"volts","sample":"41.5"},{"key":"coef","label":"Voltage change with temperature","unit":"% per deg C","sample":"-0.27"},{"key":"tmin","label":"Lowest air temperature","unit":"deg C","sample":"-5"},{"key":"tcell","label":"Hottest panel temperature","unit":"deg C","sample":"70"},{"key":"vmax","label":"Inverter maximum input voltage","unit":"volts","sample":"1100"},{"key":"vmin","label":"Inverter lowest working voltage","unit":"volts","sample":"550"}],"steps":[{"key":"voccold","label":"Open-circuit voltage on the coldest day","unit":"volts","f":"voc*(1+coef/100*(tmin-25))","x":""},{"key":"vmphot","label":"Working voltage on the hottest day","unit":"volts","f":"vmp*(1+coef/100*(tcell-25))","x":""},{"key":"most","label":"Most panels per string","unit":"count","f":"FLOOR(vmax/voccold)","x":""},{"key":"least","label":"Fewest panels per string","unit":"count","f":"CEIL(vmin/vmphot)","x":""},{"key":"ok","label":"A valid string length exists (1 yes, 0 no)","unit":"flag","f":"IF(most>=least,1,0)","x":""}],"out":["most","least","ok"],"checks":[{"label":"Voltage rises when cold","f":"voccold>voc"},{"label":"Voltage falls when hot","f":"vmphot<vmp"}],"notes":[]},{"id":"pcb-good-cost","name":"Cost per good circuit board","fn":"Costing","sectors":["Electronics and semiconductor"],"kw":["pcb","board","cost","per","good","unit","panel","yield","process","material","test","hdi","price","quote","scrap"],"about":"Works out what a good board really costs once scrap, process and test costs are included.","process":["Cost of a panel = material + process.","Divide by the boards on the panel and by the share that pass.","Add test cost for each board."],"inputs":[{"key":"material","label":"Material cost per panel","unit":"money","sample":"2400"},{"key":"process","label":"Process cost per panel","unit":"money","sample":"3600"},{"key":"n","label":"Boards per panel","unit":"count","sample":"12"},{"key":"yld","label":"Yield","unit":"%","sample":"92"},{"key":"test","label":"Test cost per board","unit":"money","sample":"35"}],"steps":[{"key":"panel","label":"Cost of a panel","unit":"money","f":"material+process","x":""},{"key":"raw","label":"Cost per board before yield loss","unit":"money","f":"panel/n","x":""},{"key":"good","label":"Cost per good board","unit":"money","f":"raw/(yld/100)+test","x":""},{"key":"lost","label":"Cost lost to scrap per good board","unit":"money","f":"raw/(yld/100)-raw","x":""}],"out":["good","lost"],"checks":[{"label":"Yield between 1 and 100","f":"AND(yld>=1,yld<=100)"},{"label":"Good board costs more than raw board","f":"good>raw"}],"notes":[]},{"id":"hdi-cost-drivers","name":"Build-up and microvia cost for a high-density board","fn":"Costing","sectors":["Electronics and semiconductor"],"kw":["hdi","build","up","layers","microvia","laser","drill","sequential","lamination","cost","adder","high","density","interconnect","board","price"],"about":"Estimates how layer count, build-up cycles and microvias raise the cost of a board.","process":["Start with the cost of a basic board.","Each pair of layers added adds a share of cost; each extra lamination cycle adds a fixed amount.","Add the cost of drilling the microvias."],"inputs":[{"key":"base","label":"Cost of a basic 4-layer board","unit":"money","sample":"120"},{"key":"layers","label":"Layer count","unit":"count","sample":"8"},{"key":"pair","label":"Cost added per extra pair of layers","unit":"%","sample":"25"},{"key":"cycles","label":"Extra lamination cycles","unit":"count","sample":"2"},{"key":"cyc","label":"Cost of each extra lamination cycle","unit":"money","sample":"18"},{"key":"vias","label":"Microvias per board","unit":"count","sample":"4500"},{"key":"per1000","label":"Cost per 1000 microvias","unit":"money","sample":"4"}],"steps":[{"key":"pairs","label":"Extra pairs of layers","unit":"count","f":"(layers-4)/2","x":""},{"key":"layercost","label":"Cost with extra layers","unit":"money","f":"base*POW(1+pair/100,pairs)","x":""},{"key":"lam","label":"Lamination cycles cost","unit":"money","f":"cycles*cyc","x":""},{"key":"via","label":"Microvia cost","unit":"money","f":"vias/1000*per1000","x":""},{"key":"total","label":"Estimated board cost","unit":"money","f":"layercost+lam+via","x":""},{"key":"uplift","label":"Above the basic board","unit":"%","f":"(total/base-1)*100","x":""}],"out":["total","uplift"],"checks":[{"label":"Layers at least 4","f":"layers>=4"}],"notes":["Teaching percentages only. Use your own factory costs."]},{"id":"rolled-yield","name":"Rolled throughput yield across process steps","fn":"Operations","sectors":["Electronics and semiconductor","Manufacturing"],"kw":["rolled","yield","throughput","process","steps","first","pass","multiply","scrap","loss","line","sequential"],"about":"Multiplies the yield of each step to show how many units survive the whole line, and how many to start for an order.","process":["Rolled yield = product of step yields.","Units to start = good units needed / rolled yield."],"inputs":[{"key":"steps","label":"Yield of each process step","unit":"series","sample":"99.2,98.5,97.8,99.5,98.9,99.7"},{"key":"need","label":"Good units wanted","unit":"units","sample":"10000"}],"steps":[{"key":"yld","label":"Rolled yield","unit":"%","f":"EXP(SUM(LN(steps/100)))*100","x":""},{"key":"start","label":"Units to start","unit":"units","f":"CEIL(need/(yld/100))","x":""},{"key":"lost","label":"Units lost along the line","unit":"units","f":"start-need","x":""},{"key":"worst","label":"Weakest step","unit":"%","f":"MIN(steps)","x":""}],"out":["yld","start","lost","worst"],"checks":[{"label":"Rolled yield not above weakest step","f":"yld<=worst+0.000001"},{"label":"Start at least the units needed","f":"start>=need"}],"notes":[]},{"id":"smt-capacity","name":"Assembly line capacity","fn":"Operations","sectors":["Electronics and semiconductor"],"kw":["smt","placement","line","capacity","components","per","board","cph","oee","boards","per","day","assembly","throughput"],"about":"Finds how many boards a placement line can build in a day.","process":["Boards per hour = placements per hour x OEE / components per board.","Multiply by working hours."],"inputs":[{"key":"cph","label":"Placement speed","unit":"components per hour","sample":"40000"},{"key":"comps","label":"Components per board","unit":"count","sample":"320"},{"key":"oee","label":"Line effectiveness","unit":"%","sample":"65"},{"key":"hours","label":"Working hours per day","unit":"hours","sample":"20"},{"key":"demand","label":"Boards wanted per day","unit":"units","sample":"1500"}],"steps":[{"key":"bph","label":"Boards per hour","unit":"units","f":"cph*oee/100/comps","x":""},{"key":"perday","label":"Boards per day","unit":"units","f":"bph*hours","x":""},{"key":"use","label":"Capacity needed for the demand","unit":"%","f":"demand/perday*100","x":""},{"key":"ok","label":"Demand can be met (1 yes, 0 no)","unit":"flag","f":"IF(use<=100,1,0)","x":""}],"out":["bph","perday","use","ok"],"checks":[{"label":"Boards per day above zero","f":"perday>0"}],"notes":[]},{"id":"trace-current","name":"Copper track current capacity","fn":"Engineering","sectors":["Electronics and semiconductor"],"kw":["trace","track","current","width","copper","thickness","temperature","rise","ampacity","pcb","external","internal","layer"],"about":"Estimates the current a copper track can carry for a chosen temperature rise, using a common published formula.","process":["Cross-section area in square mils = width in mils x thickness in mils.","Current = k x temperature rise to the power 0.44 x area to the power 0.725."],"inputs":[{"key":"width","label":"Track width","unit":"mm","sample":"0.5"},{"key":"oz","label":"Copper weight","unit":"oz per sq ft","sample":"1"},{"key":"rise","label":"Allowed temperature rise","unit":"deg C","sample":"20"},{"key":"outer","label":"Outer layer (1) or inner layer (0)","unit":"flag","sample":"1"}],"steps":[{"key":"wmil","label":"Width","unit":"mil","f":"width/0.0254","x":""},{"key":"tmil","label":"Thickness","unit":"mil","f":"oz*1.378","x":""},{"key":"area","label":"Cross-section","unit":"square mil","f":"wmil*tmil","x":""},{"key":"k","label":"Layer constant","unit":"ratio","f":"IF(outer=1,0.048,0.024)","x":""},{"key":"amps","label":"Current capacity","unit":"amps","f":"k*POW(rise,0.44)*POW(area,0.725)","x":""}],"out":["amps"],"checks":[{"label":"Current above zero","f":"amps>0"}],"notes":["The formula is a common design guide for tracks up to about 10 amps. Check your own design rules for high current."]},{"id":"microstrip-z","name":"Track impedance on the surface layer","fn":"Engineering","sectors":["Electronics and semiconductor"],"kw":["impedance","microstrip","characteristic","track","width","dielectric","height","controlled","signal","high","speed","pcb","ohm"],"about":"Estimates the impedance of a surface track over a ground layer, using a standard approximation.","process":["Impedance = 87 / root (dielectric constant + 1.41) x ln (5.98 x height / (0.8 x width + thickness)).","Valid for ratios of width to height of roughly 0.1 to 2."],"inputs":[{"key":"er","label":"Dielectric constant","unit":"ratio","sample":"4.2"},{"key":"h","label":"Height to the ground layer","unit":"mm","sample":"0.1"},{"key":"w","label":"Track width","unit":"mm","sample":"0.12"},{"key":"t","label":"Copper thickness","unit":"mm","sample":"0.018"}],"steps":[{"key":"z","label":"Impedance","unit":"ohm","f":"87/SQRT(er+1.41)*LN(5.98*h/(0.8*w+t))","x":""},{"key":"ratio","label":"Width to height","unit":"ratio","f":"w/h","x":""},{"key":"inrange","label":"Formula range respected (1 yes, 0 no)","unit":"flag","f":"IF(AND(ratio>=0.1,ratio<=2),1,0)","x":""}],"out":["z","inrange"],"checks":[{"label":"Impedance above zero","f":"z>0"},{"label":"Track lower than 8 times the height so the logarithm is valid","f":"5.98*h/(0.8*w+t)>1"}],"notes":[]},{"id":"part-junction-temp","name":"Component temperature","fn":"Engineering","sectors":["Electronics and semiconductor","Telecom and media","Manufacturing"],"kw":["junction","temperature","thermal","resistance","power","dissipation","component","heat","sink","ambient","derating","reliability"],"about":"Estimates how hot a component runs from the power it wastes and its thermal resistance.","process":["Temperature = ambient + power x total thermal resistance.","Compare with the limit, and with the derated limit used for reliability."],"inputs":[{"key":"ta","label":"Ambient temperature","unit":"deg C","sample":"55"},{"key":"p","label":"Power wasted in the part","unit":"W","sample":"2.4"},{"key":"rjc","label":"Resistance, junction to case","unit":"deg C per W","sample":"8"},{"key":"rcs","label":"Resistance, case to sink or board","unit":"deg C per W","sample":"12"},{"key":"tmax","label":"Maximum allowed junction temperature","unit":"deg C","sample":"125"},{"key":"derate","label":"Design margin below the limit","unit":"%","sample":"20"}],"steps":[{"key":"tj","label":"Junction temperature","unit":"deg C","f":"ta+p*(rjc+rcs)","x":""},{"key":"limit","label":"Derated limit","unit":"deg C","f":"ta+(tmax-ta)*(1-derate/100)","x":""},{"key":"margin","label":"Margin to derated limit","unit":"deg C","f":"limit-tj","x":""},{"key":"ok","label":"Within derated limit (1 yes, 0 no)","unit":"flag","f":"IF(tj<=limit,1,0)","x":""}],"out":["tj","margin","ok"],"checks":[{"label":"Temperature not below ambient","f":"tj>=ta"}],"notes":[]},{"id":"bom-cost","name":"Bill of materials cost","fn":"Costing","sectors":["Electronics and semiconductor","Manufacturing"],"kw":["bom","bill","of","materials","cost","components","quantity","price","scrap","allowance","overhead","assembly","product"],"about":"Totals the parts cost of a product with allowances for scrap and handling.","process":["Multiply each quantity by its unit price and add.","Add an allowance for scrap and for stock handling."],"inputs":[{"key":"qty","label":"Quantity of each part per unit","unit":"series","sample":"1,4,12,200,2,1"},{"key":"price","label":"Price of each part","unit":"series","sample":"85,12.5,3.2,0.45,20,150"},{"key":"scrap","label":"Scrap allowance","unit":"%","sample":"1.5"},{"key":"handling","label":"Purchasing and handling","unit":"%","sample":"3"}],"steps":[{"key":"line","label":"Cost of each line","unit":"series","f":"qty*price","x":""},{"key":"parts","label":"Parts cost","unit":"money","f":"SUM(line)","x":""},{"key":"total","label":"Cost per unit with allowances","unit":"money","f":"parts*(1+scrap/100)*(1+handling/100)","x":""},{"key":"big","label":"Largest line share","unit":"%","f":"MAX(line)/parts*100","x":""}],"out":["parts","total","big"],"checks":[{"label":"Same number of quantities and prices","f":"LEN(qty)=LEN(price)"}],"notes":[]},{"id":"nre-payback","name":"Tooling and development payback","fn":"Finance","sectors":["Electronics and semiconductor","Manufacturing","Technology and services"],"kw":["nre","tooling","development","cost","payback","volume","margin","per","unit","new","product","launch","break","even","years","npv"],"about":"Shows whether a new product earns back its one-time development and tooling cost.","process":["Yearly gain = units sold x margin per unit, falling or rising with yearly volume change.","Compare with the one-time cost to get payback and net present value."],"inputs":[{"key":"nre","label":"One-time development and tooling cost","unit":"money","sample":"15000000"},{"key":"units","label":"Units in year 1","unit":"units","sample":"40000"},{"key":"margin","label":"Margin per unit","unit":"money","sample":"450"},{"key":"growth","label":"Yearly change in volume","unit":"%","sample":"15"},{"key":"years","label":"Years considered","unit":"years","sample":"5"},{"key":"rate","label":"Discount rate","unit":"%","sample":"12"}],"steps":[{"key":"yrs","label":"Years","unit":"series","f":"SEQ(years)","x":""},{"key":"gain","label":"Gain each year","unit":"series","f":"units*POW(1+growth/100,yrs-1)*margin","x":""},{"key":"cf","label":"Cash flows with one-time cost","unit":"series","f":"JOIN(0-nre,gain)","x":""},{"key":"npv","label":"Net present value","unit":"money","f":"NPV0(rate/100,cf)","x":""},{"key":"payback","label":"Payback","unit":"years","f":"PAYBACK(cf)","x":""},{"key":"total","label":"Total gain over the years","unit":"money","f":"SUM(gain)","x":""}],"out":["npv","payback","total"],"checks":[{"label":"Cash flow length","f":"LEN(cf)=years+1"}],"notes":[]}];
