/* ---- formula language (same rules as the platform engine) ---- */
function bin(a,b,op){var A=Array.isArray(a),B=Array.isArray(b);if(!A&&!B)return op(a,b);if(A&&!B)return a.map(function(x){return op(x,b)});if(!A&&B)return b.map(function(y){return op(a,y)});if(a.length!==b.length)throw new Error("Two series must have the same number of items");return a.map(function(x,i){return op(x,b[i])})}
function arr(x){return Array.isArray(x)?x:[x]}function sum(x){return arr(x).reduce(function(s,v){return s+v},0)}
function fin(v){if(!isFinite(v))throw new Error("The result cannot be calculated from these numbers");return v}
function mp(x,f){return Array.isArray(x)?x.map(f):fin(f(x))}
function npv(r,cf,s){var t=0;for(var i=0;i<cf.length;i++)t+=cf[i]/Math.pow(1+r,i+s);return t}
function irr(cf){var p=cf.some(function(v){return v>0}),n=cf.some(function(v){return v<0});if(!p||!n)throw new Error("IRR needs at least one money-in and one money-out");var lo=-0.99,hi=10,fl=npv(lo,cf,0),fh=npv(hi,cf,0);if(fl*fh>0)throw new Error("IRR could not be found for these cash flows");for(var k=0;k<200;k++){var m=(lo+hi)/2,fm=npv(m,cf,0);if(fl*fm<=0)hi=m;else{lo=m;fl=fm}}return(lo+hi)/2}
function payback(cf){var run=0;for(var i=0;i<cf.length;i++){var b=run;run+=cf[i];if(run>=0&&i>0)return cf[i]===0?i:(i-1)+(-b)/cf[i]}return -1}
function nsinv(p){if(p<=0||p>=1)throw new Error("NORMSINV needs a probability between 0 and 1");var a=[-39.69683028665376,220.9460984245205,-275.9285104469687,138.357751867269,-30.66479806614716,2.506628277459239],b=[-54.47609879822406,161.5858368580409,-155.6989798598866,66.80131188771972,-13.28068155288572],c=[-0.007784894002430293,-0.3223964580411365,-2.400758277161838,-2.549732539343734,4.374664141464968,2.938163982698783],d=[0.007784695709041462,0.3224671290700398,2.445134137142996,3.754408661907416],lo=0.02425,q,r;if(p<lo){q=Math.sqrt(-2*Math.log(p));return(((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q+c[5])/((((d[0]*q+d[1])*q+d[2])*q+d[3])*q+1)}if(p>1-lo){q=Math.sqrt(-2*Math.log(1-p));return-(((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q+c[5])/((((d[0]*q+d[1])*q+d[2])*q+d[3])*q+1)}q=p-0.5;r=q*q;return(((((a[0]*r+a[1])*r+a[2])*r+a[3])*r+a[4])*r+a[5])*q/(((((b[0]*r+b[1])*r+b[2])*r+b[3])*r+b[4])*r+1)}
var FN={SUM:function(a){return sum(a[0])},AVG:function(a){return sum(a[0])/arr(a[0]).length},AVERAGE:function(a){return sum(a[0])/arr(a[0]).length},COUNT:function(a){return arr(a[0]).length},LEN:function(a){return arr(a[0]).length},
MIN:function(a){return Math.min.apply(null,a.length===1?arr(a[0]):a)},MAX:function(a){return Math.max.apply(null,a.length===1?arr(a[0]):a)},
SUMPRODUCT:function(a){if(a[0].length!==a[1].length)throw new Error("Two series must have the same number of items");return a[0].reduce(function(s,v,i){return s+v*a[1][i]},0)},
CUMSUM:function(a){var t=0;return a[0].map(function(v){t+=v;return t})},SEQ:function(a){var n=Math.floor(a[0]);if(n<1||n>1000)throw new Error("SEQ needs a whole number from 1 to 1000");var o=[];for(var i=1;i<=n;i++)o.push(i);return o},JOIN:function(a){return arr(a[0]).concat(arr(a[1]))},FIRST:function(a){return arr(a[0])[0]},LAST:function(a){var x=arr(a[0]);return x[x.length-1]},
NPV:function(a){return npv(a[0],a[1],1)},NPV0:function(a){return npv(a[0],a[1],0)},IRR:function(a){return irr(a[0])},PAYBACK:function(a){return payback(a[0])},
PMT:function(a){var r=a[0],n=a[1],pv=a[2];return r===0?pv/n:pv*r/(1-Math.pow(1+r,-n))},FV:function(a){var r=a[0],n=a[1],p=a[2];return r===0?p*n:p*(Math.pow(1+r,n)-1)/r},PV:function(a){var r=a[0],n=a[1],p=a[2];return r===0?p*n:p*(1-Math.pow(1+r,-n))/r},
IF:function(a){return a[0]!==0?a[1]:a[2]},AND:function(a){return a.every(function(v){return v!==0})?1:0},OR:function(a){return a.some(function(v){return v!==0})?1:0},
ABS:function(a){return mp(a[0],Math.abs)},SQRT:function(a){return mp(a[0],function(v){if(v<0)throw new Error("Square root of a negative number");return Math.sqrt(v)})},
LN:function(a){return mp(a[0],function(v){if(v<=0)throw new Error("LN needs a number above zero");return Math.log(v)})},EXP:function(a){return mp(a[0],Math.exp)},
SIN:function(a){return mp(a[0],Math.sin)},COS:function(a){return mp(a[0],Math.cos)},TAN:function(a){return mp(a[0],Math.tan)},LOG10:function(a){return mp(a[0],function(v){if(v<=0)throw new Error("LOG10 needs a number above zero");return Math.log10(v)})},STDEV:function(a){var x=arr(a[0]);if(x.length<2)throw new Error("STDEV needs at least two numbers");var m=sum(x)/x.length;return Math.sqrt(x.reduce(function(s,v){return s+(v-m)*(v-m)},0)/(x.length-1))},POW:function(a){return bin(a[0],a[1],Math.pow)},CEIL:function(a){return mp(a[0],Math.ceil)},FLOOR:function(a){return mp(a[0],Math.floor)},
ROUND:function(a){var p=Math.pow(10,a.length>1?a[1]:0);return mp(a[0],function(v){return Math.round(v*p)/p})},NORMSINV:function(a){return nsinv(a[0])}};
function tokenise(s){var t=[],i=0,m;while(i<s.length){var c=s[i];if(/\s/.test(c)){i++;continue}
 if(m=/^(\d+\.?\d*|\.\d+)([eE]-?\d+)?/.exec(s.slice(i))){t.push({n:parseFloat(m[0])});i+=m[0].length;continue}
 if(m=/^[A-Za-z_][A-Za-z0-9_]*/.exec(s.slice(i))){t.push({id:m[0]});i+=m[0].length;continue}
 if(m=/^(<=|>=|<>|==|[-+*\/^(),<>=])/.exec(s.slice(i))){t.push({op:m[0]});i+=m[0].length;continue}
 throw new Error("Unexpected '"+c+"' in formula")}return t}
function evalF(src,vars){var t=tokenise(src),p=0;
 function pk(){return t[p]}function eat(o){if(t[p]&&t[p].op===o){p++;return true}return false}
 function cmp(){var l=add();for(;;){var x=pk();if(x&&x.op&&["<=",">=","<>","==","<",">","="].indexOf(x.op)>=0){p++;var r=add(),o=x.op;l=bin(l,r,function(a,b){return(o==="<="?a<=b:o===">="?a>=b:o==="<>"?a!==b:o==="<"?a<b:o===">"?a>b:Math.abs(a-b)<1e-9)?1:0})}else return l}}
 function add(){var l=mul();for(;;){var x=pk();if(x&&(x.op==="+"||x.op==="-")){p++;var r=mul();l=bin(l,r,x.op==="+"?function(a,b){return a+b}:function(a,b){return a-b})}else return l}}
 function mul(){var l=un();for(;;){var x=pk();if(x&&(x.op==="*"||x.op==="/")){p++;var r=un();l=bin(l,r,x.op==="*"?function(a,b){return a*b}:function(a,b){if(b===0)throw new Error("Division by zero in: "+src);return a/b})}else return l}}
 function un(){if(eat("-"))return bin(un(),0,function(a){return-a});if(eat("+"))return un();return pw()}
 function pw(){var b=at();if(eat("^"))return bin(b,un(),Math.pow);return b}
 function at(){var x=t[p++];if(!x)throw new Error("Formula ends too soon: "+src);
  if(x.n!==undefined)return x.n;if(x.op==="("){var v=cmp();if(!eat(")"))throw new Error("Missing )");return v}
  if(x.id){if(pk()&&pk().op==="("){p++;var a=[];if(!eat(")")){do{a.push(cmp())}while(eat(","));if(!eat(")"))throw new Error("Missing )")}var f=FN[x.id.toUpperCase()];if(!f)throw new Error("Unknown function "+x.id);var rv=f(a);return typeof rv==="number"?fin(rv):rv}
   if(x.id.toUpperCase()==="PI")return Math.PI;if(vars[x.id]===undefined)throw new Error("Unknown name '"+x.id+"'");return vars[x.id]}
  throw new Error("Unexpected token in formula: "+src)}
 var v=cmp();if(p<t.length)throw new Error("Unexpected input in formula: "+src);return v}
function fmtN(d){if(d===Math.round(d)&&Math.abs(d)<1e12)return String(d);return String(+d.toPrecision(6))}
function subst(f,vars){return f.replace(/[A-Za-z_][A-Za-z0-9_]*/g,function(n,off){var rest=f.slice(off+n.length).replace(/^\s+/,"");if(rest[0]==="(")return n;var v=vars[n];return typeof v==="number"?fmtN(v):Array.isArray(v)?"{"+v.length+" items}":n})}
function runEngine(e,given){var vars={},ins=[],lines=[],checks=[];
 for(var k=0;k<e.inputs.length;k++){var i=e.inputs[k],raw=(given[i.key]||"").trim()||i.sample,v;
  if(i.unit==="series"){v=raw.split(/[,;\s]+/).map(function(s){var n=parseFloat(s);if(isNaN(n))return NaN;return n});if(v.some(isNaN))return{ok:false,error:'"'+i.label+'" needs numbers separated by commas'}}
  else{v=parseFloat(raw.replace(/,/g,"").replace("%",""));if(isNaN(v)||!/^[-+]?[\d.,]+(e-?\d+)?%?$/i.test(raw.trim()))return{ok:false,error:'"'+i.label+'" needs a number, but "'+raw+'" was given'}}
  vars[i.key]=v;ins.push({label:i.label,unit:i.unit,value:v})}
 for(var j=0;j<e.steps.length;j++){var s=e.steps[j];try{var val=evalF(s.f,vars);vars[s.key]=val;lines.push({key:s.key,label:s.label,unit:s.unit,f:s.f,wn:subst(s.f,vars),value:val,head:e.out.indexOf(s.key)>=0})}catch(x){return{ok:false,error:s.label+": "+x.message}}}
 var all=true;e.checks.forEach(function(c){var pass=false,pr="";try{var r=evalF(c.f,vars);pass=typeof r==="number"&&r!==0}catch(x){pr=x.message}all=all&&pass;checks.push({label:c.label,f:c.f,pass:pass,problem:pr})});
 return{ok:true,ins:ins,lines:lines,checks:checks,all:all}}
